def _emit(obj: dict, as_json: bool) -> None:
    if as_json:
        print(json.dumps(obj, ensure_ascii=False, indent=2, default=str))

def _out_budget(args) -> int:
    # queue 7 輸出壓縮預算：flag > env CODESEXTANT_OUTPUT_BUDGET > 預設 40
    if getattr(args, "output_budget", None) is not None:
        return args.output_budget
    try:
        return int(os.environ.get("CODESEXTANT_OUTPUT_BUDGET", "") or 40)
    except (TypeError, ValueError):
        return 40

def cmd_index(args) -> int:
    r = engine.index_project(args.path, force=args.force)
    if args.json:
        _emit(r, True)
    else:
        print(f"專案索引完成：{r['project_key'][:12]}…")
        print(f"  重算 {r['indexed']} 檔 / 跳過(cache hit) {r['skipped']} 檔 / "
              f"移除 {r['removed']} 檔 / 錯誤 {r['errors']} 檔")
        print(f"  符號總數 {r['symbols_total']}，耗時 {r['elapsed_sec']}s")
        print(f"  庫：{r['db_file']}")
        if r["errors"]:
            for ef in r["error_files"][:5]:
                print(f"    [錯誤] {ef['path']}: {ef['error']}")
    return 0

def cmd_symbols(args) -> int:
    r = engine.get_symbols(args.path, file=args.file)
    if args.json:
        _emit(r, True)
    else:
        print(f"符號數：{r['count']}（專案 {r['project_key'][:12]}…）")
        if r.get("note"):
            print(f"  注意：{r['note']}")
        for s in r["symbols"][:30]:
            scope = f"{s['scope']}." if s["scope"] else ""
            print(f"  [{s['kind']:8}] {scope}{s['name']:30} "
                  f"{s['path'].split(chr(92))[-1]}:{s['line']}")
        if r["count"] > 30:
            print(f"  …還有 {r['count'] - 30} 個")
    return 0

def cmd_references(args) -> int:
    r = engine.find_references(
        args.path, args.symbol,
        def_path=args.def_path, src_root=args.src_root,
        include_low_confidence=not args.no_low,
    )
    if args.json:
        _emit(r, True)
    else:
        print(f"找引用：'{r['symbol']}'")
        if r.get("error"):
            print(f"  ⚠ {r['error']}")
        d = r.get("definition")
        if d:
            print(f"  定義：{d['path']}:{d['line']}")
        hc = r["high_confidence"]
        print(f"  高信心引用（jedi 確認）：{len(hc)} 處")
        for ref in hc[:20]:
            print(f"    {ref['src_path']}:{ref['line']}:{ref['column']}")
        print(f"  名稱比對會框到 {r['name_match_file_count']} 個檔（對比基準）；"
              f"低信心（未經 jedi 確認）{len(r['low_confidence'])} 檔")
        cands = r.get("candidate_definitions", [])
        if len(cands) > 1:
            print(f"  ⚠ 同名定義有 {len(cands)} 個（名稱比對無法分辨，jedi 才行）：")
            for c in cands[:10]:
                print(f"    {c['path']}:{c['line']} (scope={c['scope'] or '模組頂層'})")
        # 序6：可靠度自評（low/medium 喊讀碼）
        rel = r.get("reliability") or {}
        if rel.get("level"):
            mark = "✅" if rel["level"] == "high" else "⚠"
            print(f"  {mark} 可靠度 {rel['level']}：{rel.get('advice')}")
    return 0

def cmd_map(args) -> int:
    r = engine.get_map(args.path, token_budget=args.budget)
    if args.json:
        _emit(r, True)
    else:
        print(f"代碼地圖（token 預算 {r['token_budget']} ≈ {r['approx_tokens']}，"
              f"取最重要 {r['count']} 個符號）")
        if r.get("note"):
            print(f"  注意：{r['note']}")
        # queue 7：符號已按 PageRank 排序，compress 截斷尾端低排名 + 麵包屑可展開
        cs = fl.compress([fl.Section("syms", "符號", list(r["symbols"]))],
                         budget=_out_budget(args), full=args.full)[0]
        for i, s in enumerate(cs.shown, 1):
            scope = f"{s['scope']}." if s["scope"] else ""
            print(f"  {i:3}. [{s['rank']:.4f}] [{s['kind']:8}] {scope}{s['name']:28} "
                  f"{s['path'].split(chr(92))[-1]}:{s['line']}")
        if cs.elided:
            print(f"  …（另 {cs.elided} 個較低排名符號省略，--full 看全部）")
    return 0

def cmd_status(args) -> int:
    r = engine.status(args.path)
    if args.json:
        _emit(r, True)
    else:
        if not r["indexed"]:
            print(f"專案尚未索引：{r['repo_path']}")
            print(f"  （庫位置會是 {r['db_file']}）")
        else:
            print(f"專案：{r['repo_path']}")
            print(f"  project_key：{r['project_key']}")
            print(f"  已索引 {r['indexed_files']} 檔 / {r['symbols']} 符號 / "
                  f"{r['refs']} 引用邊")
            print(f"  庫：{r['db_file']}")
    return 0

def cmd_deadcode(args) -> int:
    r = engine.find_deadcode(args.path, scope_file=args.file, lang=args.lang)
    if args.json:
        _emit(r, True)
    else:
        ui = r.get("unused_imports", {}) or {}
        if ui.get("available"):
            fs = ui.get("findings", []) or []
            print(f"未使用 import（linter={ui.get('linter')}）：{len(fs)} 處")
            for f in fs[:20]:
                print(f"  {f.get('path')}:{f.get('line')} [{f.get('code')}] {f.get('message')}")
        else:
            print(f"未使用 import = UNKNOWN（{ui.get('reason')}）")
        if r.get("scope_file"):
            print(f"孤兒符號分級（{r['scope_file']}）：")
            for o in r.get("orphans", []) or []:
                print(f"  {o.get('icon', '·')} {o.get('verdict')} {o.get('kind')} "
                      f"{o.get('name')} @line {o.get('line')} — {o.get('reason')}")
        s = r.get("summary", {}) or {}
        print(f"小結：unused={s.get('unused_import_count', 0)} "
              f"likely_unused={s.get('likely_unused', 0)} keep={s.get('keep', 0)} "
              f"unknown={s.get('unknown', 0)}")
        # 序6：工具盲區攤開（必須人工讀碼）
        for a in r.get("read_code_advisory", []) or []:
            print(f"  🔎 {a}")
    return 0

def cmd_comment_overview(args) -> int:
    r = engine.get_comment_overview(args.path, scope_file=args.file)
    if args.json:
        _emit(r, True)
    elif not r.get("indexed"):
        print(f"專案尚未索引：{r.get('note')}")
    else:
        cov = r["docstring_coverage"]
        print(f"docstring 覆蓋率（{'/'.join(cov['counted_kinds'])}，"
              f"skip_private={cov['skip_private']}）：{cov['overall_pct']}%")
        for k, v in cov["by_kind"].items():
            print(f"  {k:10} {v['documented']}/{v['total']} ({v['pct']}%)")
        if r["tag_counts"]:
            print(f"標記計數：{r['tag_counts']}")
        if r["density"]:
            dd = r["density"]
            print(f"密度：{dd['comment_lines']} 註解行 / {dd['code_lines']} 程式行 = {dd['ratio']}")
        for u in r["top_undocumented"][:10]:
            print(f"  ✗ {u['kind']} {u['name']} @ {u['path'].split(chr(92))[-1]}:{u['line']}")
        print(f"  🔎 {r['caveat']}")
    return 0

def cmd_comment_tags(args) -> int:
    tags = [t for t in args.tags.split(",") if t] if args.tags else None
    r = engine.find_comment_tags(args.path, tags=tags, scope_file=args.file)
    if args.json:
        _emit(r, True)
    elif not r.get("indexed"):
        print(r.get("note"))
    else:
        print(f"標記索引：{r['count_by_tag']}")
        cs = fl.compress([fl.Section("t", "標記", list(r["findings"]), min_keep=5)],
                         budget=_out_budget(args), full=args.full)[0]
        for f in cs.shown:
            print(f"  [{f['tag']}] {f['path'].split(chr(92))[-1]}:{f['line']} — {f['text']}")
        if cs.elided:
            print(f"  …（另 {cs.elided} 省略，--full）")
    return 0

def cmd_comments(args) -> int:
    r = engine.get_comments(args.path, file=args.file, scope=args.scope,
                            doc_only=args.doc_only, tag=args.tag)
    if args.json:
        _emit(r, True)
    else:
        print(f"註解數：{r['count']}")
        for c in r["comments"][:30]:
            mark = "/doc" if c["is_doc"] else ("/" + (c["tag"] or "") if c["tag"] else "")
            print(f"  L{c['line']} [{c['kind']}{mark}] {c['text'][:60]!r}")
    return 0

def cmd_duplicates(args) -> int:
    r = engine.find_duplicates(args.path, scope_file=args.file, near_global=args.near_global,
                               min_similarity=args.min_similarity, include_call_pattern=args.calls)
    if args.json:
        _emit(r, True)
    else:
        s = r["summary"]
        print(f"重複/類似偵測：掃 {s['total_units_scanned']} 單元 → EXACT {s['exact']} / "
              f"RENAMED {s['renamed']} / NEAR {s['structural_near']} / CALL {s['call_pattern']} / "
              f"壓制 {s['boilerplate_suppressed_groups']} 群（stage2_ran={s['stage2_ran']}）")
        cs = fl.compress([fl.Section("g", "群", list(r["groups"]), min_keep=5)],
                         budget=_out_budget(args), full=args.full)[0]
        for g in cs.shown:
            mem = ", ".join(f"{m['path'].split(chr(92))[-1]}:{m['line']} {m['name']}"
                            for m in g["members"])
            sim = f" sim={g['similarity']}" if g["similarity"] is not None else ""
            print(f"  {g['icon']} {g['verdict']}{sim}: {mem}")
        if cs.elided:
            print(f"  …（另 {cs.elided} 群省略，--full）")
        for a in r["read_code_advisory"]:
            print(f"  🔎 {a}")
        print(f"  ⚠ {r['verification_reminder']}")
    return 0

def cmd_impact(args) -> int:
    r = engine.impact(args.path, args.symbol, max_hops=args.max_hops,
                      src_root=args.src_root, def_path=args.def_path)
    if args.json:
        _emit(r, True)
    else:
        s = r.get("summary", {}) or {}
        print(f"改動影響：改 '{r['symbol']}' 牽動 {s.get('total_confirmed_affected', 0)} 個"
              f"（直接 {s.get('direct', 0)}/傳遞 {s.get('transitive', 0)}）")
        print(f"  prod={s.get('prod', 0)} test={s.get('test', 0)} "
              f"entrypoint={s.get('entrypoint', 0)} high_importance={s.get('high_importance', 0)} "
              f"uncertain={s.get('uncertain', 0)}")
        # queue 7：高重要度受影響 min_keep 全留（最該看的不省）+ 麵包屑
        hi = r.get("high_importance_affected") or []
        cs = fl.compress([fl.Section("hi", "高重要度", list(hi), priority=10, min_keep=len(hi))],
                         budget=_out_budget(args), full=args.full)[0]
        for c in cs.shown:
            print(f"  ⭐ {c['name']} @ {c['path'].split(chr(92))[-1]}:{c['line']}")
        if cs.elided:
            print(f"  …（另 {cs.elided} 省略，--full）")
        if r.get("error"):
            print(f"  ⚠ {r['error']}")
    return 0

def main(argv=None) -> int:
    parser = _build_parser()
    args = parser.parse_args(argv)
    return args.func(args)

class CodesextantClient:
    """瘦 HTTP 客戶端 + 自動冪等 ensure + 自動帶 project。

    參數
    ----
    project : 當前 repo 絕對路徑（C3 Skill 自動帶當前專案＝這個）。
              daemon 端會用 storage.project_key=sha1(abs path) 分庫，不混線。
    port    : daemon port（預設讀 CODESEXTANT_PORT 或 8790）。
    """

    def __init__(self, project: str | None = None, port: int | None = None,
                 timeout: float = 30.0):
        self.project = os.path.abspath(project) if project else None
        self.port = port or daemon._port()
        self.timeout = timeout
        self.base = f"http://{daemon.HOST}:{self.port}"

    # ── 冪等確保（C3 Skill 觸發第一步）──
    def ensure(self) -> dict:
        """確保 daemon 在跑（已在跑就不重開）。回傳 ensure_running 的結果。"""
        return daemon.ensure_running(port=self.port)

    def is_up(self) -> bool:
        return daemon.http_ping(port=self.port) is not None

    # ── HTTP 基本動作 ──
    def _get(self, path: str, params: dict) -> dict:
        qs = urllib.parse.urlencode({k: v for k, v in params.items() if v is not None})
        url = f"{self.base}{path}?{qs}" if qs else f"{self.base}{path}"
        with urllib.request.urlopen(url, timeout=self.timeout) as r:
            return json.loads(r.read().decode("utf-8"))

    def _post(self, path: str, body: dict) -> dict:
        data = json.dumps(body, ensure_ascii=False).encode("utf-8")
        req = urllib.request.Request(
            f"{self.base}{path}", data=data, method="POST",
            headers={"Content-Type": "application/json; charset=utf-8"},
        )
        with urllib.request.urlopen(req, timeout=self.timeout) as r:
            return json.loads(r.read().decode("utf-8"))

    def _proj(self, project: str | None) -> str:
        p = project or self.project
        if not p:
            raise ValueError("CodesextantClient：未指定 project（repo 絕對路徑）")
        return os.path.abspath(p)

    # ── 三查詢介面 + 維護介面（對齊 daemon 端點）──
    def health(self) -> dict:
        return self._get("/health", {})

    def status(self, project: str | None = None, *, fresh: bool = False) -> dict:
        # fresh=True → 帶 ?fresh=1 讓 daemon 比對 git HEAD sha 新鮮度（坑6；預設 lazy 不查，
        # 避免不設防 GET 觸發 git spawn）。回傳含 git_stale / indexed_git_sha / current_git_sha。
        return self._get("/status", {"project": self._proj(project),
                                     "fresh": "1" if fresh else None})

    def get_symbols(self, file: str | None = None, project: str | None = None) -> dict:
        return self._get("/get_symbols", {"project": self._proj(project), "file": file})

    def get_map(self, budget: int = 2000, project: str | None = None,
                focus_symbols=None, focus_files=None) -> dict:
        # queue 4：focus_symbols/focus_files（list）→ 逗號分隔給 daemon query-aware 排序
        return self._get("/get_map", {
            "project": self._proj(project), "budget": budget,
            "focus_symbols": ",".join(focus_symbols) if focus_symbols else None,
            "focus_files": ",".join(focus_files) if focus_files else None})

    def find_references(self, symbol: str, *, def_path: str | None = None,
                        src_root: str | None = None, project: str | None = None,
                        include_low_confidence: bool = True,
                        persist: bool = True) -> dict:
        return self._post("/find_references", {
            "project": self._proj(project), "symbol": symbol,
            "def_path": def_path, "src_root": src_root,
            "include_low_confidence": include_low_confidence, "persist": persist,
        })

    def reindex(self, force: bool = False, project: str | None = None) -> dict:
        return self._post("/reindex", {"project": self._proj(project), "force": force})

    def find_deadcode(self, scope_file: str | None = None, lang: str | None = None,
                      project: str | None = None) -> dict:
        # 序3：死碼線索層。scope_file 給了才跑 orphan（對該檔逐符號真解析）。
        return self._get("/deadcode", {"project": self._proj(project),
                                       "file": scope_file, "lang": lang})

    def find_unwired(self, max_fanout: int | None = None,
                     project: str | None = None) -> dict:
        # 功能 A：未接線檢查（namegraph 名稱級全圖粗篩零外部引用頂層符號；低信心線索層）。
        return self._get("/find_unwired", {"project": self._proj(project),
                                           "max_fanout": max_fanout})

    def get_health(self, project: str | None = None) -> dict:
        # 紀律轉美：per-symbol 代碼健康度（低=該讀碼複核處；線索非決策、⛔不出應刪）。
        return self._get("/get_health", {"project": self._proj(project)})

    # ── 功能 B：註解管理 + 重複偵測 ──
    def get_comment_overview(self, file: str | None = None, project: str | None = None) -> dict:
        return self._get("/comment_overview", {"project": self._proj(project), "file": file})

    def find_comment_tags(self, tags: list[str] | None = None, file: str | None = None,
                          project: str | None = None) -> dict:
        return self._get("/comment_tags", {"project": self._proj(project), "file": file,
                                           "tags": ",".join(tags) if tags else None})

    def get_comments(self, file: str | None = None, scope: str | None = None,
                     doc_only: bool = False, tag: str | None = None,
                     project: str | None = None) -> dict:
        return self._get("/get_comments", {"project": self._proj(project), "file": file,
                                           "scope": scope, "tag": tag,
                                           "doc_only": "1" if doc_only else None})

    def find_duplicates(self, file: str | None = None, near_global: bool = False,
                        min_similarity: float | None = None,
                        include_call_pattern: bool = False, project: str | None = None) -> dict:
        # 重複/類似偵測。near_global=全域近似 opt-in、calls=開 call_pattern。
        return self._get("/find_duplicates", {"project": self._proj(project), "file": file,
                                              "near_global": "1" if near_global else None,
                                              "min_similarity": min_similarity,
                                              "calls": "1" if include_call_pattern else None})

    def call_hierarchy(self, symbol: str, *, direction: str = "both",
                       max_hops: int | None = None, def_path: str | None = None,
                       src_root: str | None = None, project: str | None = None) -> dict:
        # 競品吸收 queue 1：傳遞呼叫鏈。direction up=callers/down=callees/both。
        return self._post("/call_hierarchy", {
            "project": self._proj(project), "symbol": symbol,
            "direction": direction, "max_hops": max_hops,
            "def_path": def_path, "src_root": src_root})

    def impact(self, symbol: str, *, max_hops: int | None = None,
               def_path: str | None = None, src_root: str | None = None,
               project: str | None = None) -> dict:
        # 競品吸收 queue 2：改動影響 / blast radius（改 X 會牽動誰）。
        return self._post("/impact", {
            "project": self._proj(project), "symbol": symbol,
            "max_hops": max_hops, "def_path": def_path, "src_root": src_root})

def ensure(self) -> dict:
    """確保 daemon 在跑（已在跑就不重開）。回傳 ensure_running 的結果。"""
    return daemon.ensure_running(port=self.port)

def _get(self, path: str, params: dict) -> dict:
    qs = urllib.parse.urlencode({k: v for k, v in params.items() if v is not None})
    url = f"{self.base}{path}?{qs}" if qs else f"{self.base}{path}"
    with urllib.request.urlopen(url, timeout=self.timeout) as r:
        return json.loads(r.read().decode("utf-8"))

def _post(self, path: str, body: dict) -> dict:
    data = json.dumps(body, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(
        f"{self.base}{path}", data=data, method="POST",
        headers={"Content-Type": "application/json; charset=utf-8"},
    )
    with urllib.request.urlopen(req, timeout=self.timeout) as r:
        return json.loads(r.read().decode("utf-8"))

def _proj(self, project: str | None) -> str:
    p = project or self.project
    if not p:
        raise ValueError("CodesextantClient：未指定 project（repo 絕對路徑）")
    return os.path.abspath(p)

def status(self, project: str | None = None, *, fresh: bool = False) -> dict:
    # fresh=True → 帶 ?fresh=1 讓 daemon 比對 git HEAD sha 新鮮度（坑6；預設 lazy 不查，
    # 避免不設防 GET 觸發 git spawn）。回傳含 git_stale / indexed_git_sha / current_git_sha。
    return self._get("/status", {"project": self._proj(project),
                                 "fresh": "1" if fresh else None})

