                    src_root: str | None = None, project: str | None = None,
                    include_low_confidence: bool = True,
                    persist: bool = True) -> dict:
    return self._post("/find_references", {
        "project": self._proj(project), "symbol": symbol,
        "def_path": def_path, "src_root": src_root,
        "include_low_confidence": include_low_confidence, "persist": persist,
    })

def find_deadcode(self, scope_file: str | None = None, lang: str | None = None,
                  project: str | None = None) -> dict:
    # 序3：死碼線索層。scope_file 給了才跑 orphan（對該檔逐符號真解析）。
    return self._get("/deadcode", {"project": self._proj(project),
                                   "file": scope_file, "lang": lang})

def find_unwired(self, max_fanout: int | None = None,
                 project: str | None = None) -> dict:
    # 功能 A：未接線檢查（namegraph 名稱級全圖粗篩零外部引用頂層符號；低信心線索層）。
    return self._get("/find_unwired", {"project": self._proj(project),
                                       "max_fanout": max_fanout})

def get_health(self, project: str | None = None) -> dict:
    # 紀律轉美：per-symbol 代碼健康度（低=該讀碼複核處；線索非決策、⛔不出應刪）。
    return self._get("/get_health", {"project": self._proj(project)})

def find_comment_tags(self, tags: list[str] | None = None, file: str | None = None,
                      project: str | None = None) -> dict:
    return self._get("/comment_tags", {"project": self._proj(project), "file": file,
                                       "tags": ",".join(tags) if tags else None})

def get_comments(self, file: str | None = None, scope: str | None = None,
                 doc_only: bool = False, tag: str | None = None,
                 project: str | None = None) -> dict:
    return self._get("/get_comments", {"project": self._proj(project), "file": file,
                                       "scope": scope, "tag": tag,
                                       "doc_only": "1" if doc_only else None})

_IDENT_TYPES = {
    "identifier", "property_identifier", "field_identifier", "type_identifier",
    "shorthand_property_identifier", "shorthand_property_identifier_pattern",
    "private_property_identifier", "statement_identifier", "label_name",
}

def _env_int(name: str, default: int) -> int:
    try:
        v = int(os.environ.get(name, ""))
        return v if v > 0 else default
    except ValueError:
        return default

def _env_float(name: str, default: float) -> float:
    # 紅隊 L4-LOW：NaN 保護（'nan' 會讓 `sim < nan` 恆 False＝門檻形同關閉）；越界 clamp 由消費端做。
    import math
    try:
        v = float(os.environ.get(name, ""))
    except ValueError:
        return default
    return v if not math.isnan(v) else default

def _shape_tokens(src: bytes, body) -> list[str]:
    """前序遍歷 node-type 序列：identifier→ID、literal→LIT、丟匿名標點/註解、保留結構+關鍵字命名節點。"""
    toks: list[str] = []

    def rec(n):
        t = n.type
        if not n.is_named:          # 匿名 token（標點、字面關鍵字符號）→ 丟（保留的是結構命名節點）
            return
        if t in _COMMENT_LIKE:
            return
        if t in _IDENT_TYPES:
            toks.append("ID")       # 葉子，抹值不下鑽
            return
        if t in _LITERAL_TYPES:
            toks.append("LIT")
            return
        toks.append(t)
        for c in n.children:
            rec(c)

    rec(body)
    return toks

def rec(n):
    t = n.type
    if not n.is_named:          # 匿名 token（標點、字面關鍵字符號）→ 丟（保留的是結構命名節點）
        return
    if t in _COMMENT_LIKE:
        return
    if t in _IDENT_TYPES:
        toks.append("ID")       # 葉子，抹值不下鑽
        return
    if t in _LITERAL_TYPES:
        toks.append("LIT")
        return
    toks.append(t)
    for c in n.children:
        rec(c)

def _raw_tokens(src: bytes, body) -> list[str]:
    """terminal token 原值串接（保留 identifier/literal 實際值，給逐字 Type-1 判定）。"""
    toks: list[str] = []

    def rec(n):
        if n.type in _COMMENT_LIKE:
            return
        if n.child_count == 0:      # terminal token
            txt = _node_text(src, n)
            if txt.strip():
                toks.append(txt)
        else:
            for c in n.children:
                rec(c)

    rec(body)
    return toks

def rec(n):
    if n.type in _COMMENT_LIKE:
        return
    if n.child_count == 0:      # terminal token
        txt = _node_text(src, n)
        if txt.strip():
            toks.append(txt)
    else:
        for c in n.children:
            rec(c)

def _last_identifier(src: bytes, node) -> str | None:
    """取被呼叫名的最後一段 identifier（a.b.c → c；單 identifier → 自己）。"""
    last = None

    def rec(n):
        nonlocal last
        if n.type in _IDENT_TYPES:
            last = _node_text(src, n)
        for c in n.children:
            rec(c)

    rec(node)
    return last

def rec(n):
    nonlocal last
    if n.type in _IDENT_TYPES:
        last = _node_text(src, n)
    for c in n.children:
        rec(c)

def _call_names(src: bytes, body, lang_key: str) -> list[str]:
    """body 內所有呼叫節點的被呼叫名 sorted multiset（呼叫模式指紋原料）。"""
    call_types = _CALL_TYPES.get(lang_key, {"call_expression"})
    names: list[str] = []

    def rec(n):
        if n.type in call_types:
            # 被呼叫名的 field 跨語言不同（function=C系/name=Java·Lua/method=Ruby）→ 試常見 field 容錯
            fn = (n.child_by_field_name("function")
                  or n.child_by_field_name("name")
                  or n.child_by_field_name("method"))
            if fn is not None and fn.type not in _SUBSCRIPT_TYPES:
                nm = _last_identifier(src, fn)
                if nm:
                    names.append(nm)
        for c in n.children:
            rec(c)

    rec(body)
    return sorted(names)

def rec(n):
    if n.type in call_types:
        # 被呼叫名的 field 跨語言不同（function=C系/name=Java·Lua/method=Ruby）→ 試常見 field 容錯
        fn = (n.child_by_field_name("function")
              or n.child_by_field_name("name")
              or n.child_by_field_name("method"))
        if fn is not None and fn.type not in _SUBSCRIPT_TYPES:
            nm = _last_identifier(src, fn)
            if nm:
                names.append(nm)
    for c in n.children:
        rec(c)

def _metadata(body) -> tuple[int, int, bool]:
    """(node_count=named 子孫數, nstmts=body 直接 named children 數, has_control_flow)。"""
    node_count = 0
    has_cf = False

    def rec(n):
        nonlocal node_count, has_cf
        if n.is_named:
            node_count += 1
            if n.type in _CONTROL_FLOW:
                has_cf = True
        for c in n.children:
            rec(c)

    rec(body)
    return node_count, body.named_child_count, has_cf

def rec(n):
    nonlocal node_count, has_cf
    if n.is_named:
        node_count += 1
        if n.type in _CONTROL_FLOW:
            has_cf = True
    for c in n.children:
        rec(c)

def _kgram_hash(kgram: tuple) -> int:
    """k-gram → crc32（標準庫、快、跨進程穩定、零依賴）。"""
    return zlib.crc32("\x1f".join(kgram).encode("utf-8")) & 0xFFFFFFFF

def walk(node, scope_parts: list[str]) -> None:
    child_scope = scope_parts
    if node.type in always:
        # 套 name_rules（與 symbols.extract_symbols 一致）；有 name field 的語言 rule=None→_name_of 不變行為。
        # ⛔ 原直接 _name_of 不套 rule → C/C++/Kotlin fingerprint name 全 <anon>（dedup/cognitive 落盤名失真）
        name = symbols._extract_name(source, node, name_rules.get(node.type))
        if always[node.type] in ("function", "method"):
            fp = _fingerprint_unit(source, node, lang_key, func_name=name,
                                   min_node_count=min_node_count)
            if fp is not None:
                fp.update({"name": name, "kind": always[node.type],
                           "line": node.start_point[0] + 1,
                           "end_line": node.end_point[0] + 1,
                           "scope": ".".join(scope_parts)})
                out.append(fp)
        child_scope = scope_parts + [name]
    elif node.type in scope_only:
        fld = node.child_by_field_name(scope_only[node.type])
        if fld is not None:
            child_scope = scope_parts + [_node_text(source, fld)]
    for c in node.children:
        walk(c, child_scope)

def extract_fingerprints(file_path: str, *, min_node_count: int | None = None) -> list[dict]:
    """讀檔抽指紋。副檔名不支援 → ValueError；讀不到 → FileNotFoundError。"""
    lang_key = symbols.language_for_file(file_path)
    if lang_key is None:
        raise ValueError(f"抽指紋失敗：不支援的副檔名 {file_path}")
    try:
        with open(file_path, "rb") as f:
            source = f.read()
    except OSError as exc:
        raise FileNotFoundError(f"抽指紋失敗：讀不到檔 {file_path}（{exc}）") from exc
    return extract_fingerprints_from_source(source, lang_key, file_path=file_path,
                                            min_node_count=min_node_count)

def comments_enabled() -> bool:
    return os.environ.get("CODESEXTANT_COMMENTS_DISABLED", "").lower() not in (
        "1", "true", "yes", "on")

def markers() -> list[str]:
    raw = os.environ.get("CODESEXTANT_COMMENT_MARKERS", "TODO,FIXME,HACK,XXX,BUG,NOTE")
    return [m.strip() for m in raw.split(",") if m.strip()]

def _marker_re() -> "re.Pattern | None":
    ms = markers()
    if not ms:
        return None
    return re.compile(r"\b(" + "|".join(re.escape(m) for m in ms) + r")\b")

def _first_marker(text: str, marker_re) -> str | None:
    if marker_re is None:
        return None
    m = marker_re.search(text)
    return m.group(1) if m else None

def _is_doc(node_type: str, text: str) -> bool:
    if node_type == "doc_comment":
        return True
    t = text.lstrip()
    return any(t.startswith(p) for p in _DOC_PREFIXES)

def _docstring_string_node(def_node, src: bytes):
    """function/class 定義節點的 docstring string 節點（body 第一個 named child 若 string；
    含 expression_statement 包裹一層的相容處理）。非 string → None。"""
    body = def_node.child_by_field_name("body")
    if body is None or body.named_child_count == 0:
        return None
    first = body.named_child(0)
    if first is None:
        return None
    if first.type == "string":
        return first
    if first.type == "expression_statement" and first.named_child_count > 0:
        inner = first.named_child(0)
        if inner is not None and inner.type == "string":
            return inner
    return None

def _add_pending_owner(def_line: int) -> None:
    if pending_doc and pending_doc[0] is not None:
        d = pending_doc[0]
        # 緊鄰才回填（定義行 - doc end_line ∈ [0,2]，容 tree-sitter comment 含尾換行的
        # off-by-one〔end_point 落在下一行開頭〕+ 一個空行）
        if 0 <= def_line - d["end_line"] <= 2:
            d["owner_line"] = def_line
    pending_doc.clear()

def extract_comments(file_path: str) -> list[dict]:
    """讀一個原始碼檔，按副檔名抽註解。副檔名不支援 → ValueError；讀不到 → FileNotFoundError。"""
    lang_key = symbols.language_for_file(file_path)
    if lang_key is None:
        raise ValueError(
            f"抽註解失敗：不支援的副檔名 {file_path}（支援：{sorted(symbols.SUPPORTED_EXTENSIONS)}）")
    try:
        with open(file_path, "rb") as f:
            source = f.read()
    except OSError as exc:
        raise FileNotFoundError(f"抽註解失敗：讀不到檔 {file_path}（{exc}）") from exc
    return extract_comments_from_source(source, lang_key, file_path=file_path)

_BINARY_CALLEE_WRAP = {"multiplicative_expression", "additive_expression",
                       "comparison_expression", "equality_expression",
                       "conjunction_expression", "disjunction_expression"}

def supported(lang_key: str) -> bool:
    """該語言是否高信心計分（其餘語言 cognitive=None UNKNOWN）。"""
    return lang_key in COGNITIVE_SPECS and not _env_on("CODESEXTANT_COGNITIVE_DISABLED")

_BODY_FALLBACK_TYPES: dict[str, set] = {
    "kotlin": {"function_body"},
}

def function_body(def_node, lang_key: str):
    """取 function/method 定義節點的 body 節點（無 → None）。Kotlin 走 function_body fallback。"""
    if def_node is None:
        return None
    b = def_node.child_by_field_name("body")
    if b is not None:
        return b
    fallback = _BODY_FALLBACK_TYPES.get(lang_key)
    if fallback:
        for c in def_node.children:
            if c.type in fallback:
                return c
    return None

def _op_text(node, src: bytes) -> str:
    op = node.child_by_field_name("operator")
    return _node_text(op, src) if op is not None else ""

def cognitive_complexity(body, lang_key: str, func_name: str | None = None,
                         src: bytes = b"") -> int | None:
    """算 function body 的 cognitive complexity。非高信心語言/關閉/body=None → None（UNKNOWN）。

    body=function 的 body node；func_name=函數名（直接遞迴 +1）；src=原始 bytes（取 operator/callee 文字）。
    """
    spec = COGNITIVE_SPECS.get(lang_key)
    if spec is None or body is None or _env_on("CODESEXTANT_COGNITIVE_DISABLED"):
        return None

    incr_nest = spec["incr_nest"]
    if_types = spec["if_types"]
    if_style = spec["if_style"]
    elif_t = spec["elif"]
    else_t = spec["else"]
    transparent = spec["transparent"]
    nest_only = spec["nest_only"]
    comp_for = spec["comp_for"]
    comp_if = spec["comp_if"]
    boolean = spec["boolean"]
    bool_ops = spec["bool_ops"]
    bool_type_ops = spec.get("bool_type_ops")   # P5：節點型別→運算子（Kotlin/Swift conjunction/disjunction）
    call_t = spec["call"]
    callee_field = spec["callee_field"]
    labeled_jump = spec["labeled_jump"]
    label_child_types = spec["label_child_types"]
    jump_keywords = spec.get("jump_keywords")   # P5：Swift control_transfer 區分 continue/break vs return
    _dbg = _env_on("CODESEXTANT_COG_DEBUG")     # debug trace（env-gated、熱路徑只讀一次）

    total = 0

    def is_logical(n) -> bool:
        if bool_type_ops is not None:
            return n.type in bool_type_ops
        return n.type in boolean and _op_text(n, src) in bool_ops

    def is_bool_root(n) -> bool:
        # 是否為一個布林表達式的最外層 logical 節點（往上若遇另一個 logical 祖先＝非根）。
        # bool_type_ops 語言（Kotlin/Swift）用此判定，避免 grammar 把 a&&b||c 拆成 conjunction/disjunction
        # 多節點各自獨立觸發而 double-count（尤其 Swift 運算子優先級畸形把 logical 埋在 comparison 下）。
        p = n.parent
        while p is not None:
            if is_logical(p):
                return False
            p = p.parent
        return True

    def count_bool_runs(node) -> int:
        """連續邏輯運算子：中序收集 operator，數「相鄰不同」的 run 數（a&&b||c=2）。"""
        ops: list[str] = []

        if bool_type_ops is not None:
            # Kotlin/Swift：&&/|| 是不同節點型別、operand 無 left/right field（用位置 named children）；
            # 穿過非 logical 中間層（Swift grammar 運算子優先級畸形會把 logical 埋在 comparison 之下）。
            def collect(n):
                kids = [c for c in n.children if c.is_named]
                if n.type in bool_type_ops:
                    if kids:
                        collect(kids[0])
                    ops.append(bool_type_ops[n.type])
                    for kk in kids[1:]:
                        collect(kk)
                else:
                    for kk in kids:
                        collect(kk)
        else:
            def collect(n):
                if is_logical(n):
                    left = n.child_by_field_name("left")
                    right = n.child_by_field_name("right")
                    if left is not None:
                        collect(left)
                    ops.append(_op_text(n, src))
                    if right is not None:
                        collect(right)

        collect(node)
        if not ops:
            return 0
        runs = 1
        for i in range(1, len(ops)):
            if ops[i] != ops[i - 1]:
                runs += 1
        return runs

    def is_labeled(node) -> bool:
        # 帶 label 才算（裸 break/continue 不算）；各語言 label child 型別不同（per-spec）。
        # jump_keywords（Swift）：control_transfer_statement 統一 continue/break/return，須第一個 child
        # （keyword token）∈ jump_keywords 才算（防 `return x` 的 simple_identifier result 誤判 label）。
        if jump_keywords is not None:
            kids = node.children
            if not kids or kids[0].type not in jump_keywords:
                return False
        return any(c.type in label_child_types for c in node.children)

    def is_direct_recursion(call_node) -> bool:
        # 直接遞迴：裸 identifier==func_name，或 self/cls/this.<func_name>；
        # ⛔ 跨物件同名方法 obj.foo() 於名為 foo 的函數內不算（對抗 review MEDIUM 收緊誤判）
        if callee_field is not None:
            fn = call_node.child_by_field_name(callee_field)
        else:
            # Kotlin/Swift call_expression 無 callee field → callee＝第一個 named child
            # （裸呼叫=simple_identifier；member 呼叫=navigation_expression、走下方 navigation 分支）
            fn = next((c for c in call_node.children if c.is_named), None)
            # Swift 算術/比較外包（n * fact(n-1)）：callee 是 binary expression → 下鑽最末 operand 取真 callee
            seen = 0
            while fn is not None and fn.type in _BINARY_CALLEE_WRAP and seen < 8:
                seen += 1
                rhs = fn.child_by_field_name("rhs")
                if rhs is None:
                    named = [c for c in fn.children if c.is_named]
                    rhs = named[-1] if named else None
                fn = rhs
        if fn is None:
            return False
        if fn.type in _IDENT_TYPES:
            # 有 receiver/object 且非 self/this/cls → 跨物件同名、不算（Java/C# object、Ruby receiver）
            cobj = (call_node.child_by_field_name("object")
                    or call_node.child_by_field_name("receiver"))
            if cobj is not None and _node_text(cobj, src) not in ("self", "cls", "this"):
                return False
            return _node_text(fn, src) == func_name
        if fn.type == "navigation_expression":
            # Kotlin/Swift member 呼叫 this.f()/self.f()：navigation_expression
            #   Kotlin（無 field）：[this_expression/identifier, navigation_suffix > simple_identifier]
            #   Swift（有 field）：target field（self_expression）、suffix field（navigation_suffix > simple_identifier）
            tgt = (fn.child_by_field_name("target")
                   or next((c for c in fn.children if c.is_named), None))
            suf = (fn.child_by_field_name("suffix")
                   or next((c for c in fn.children if c.type == "navigation_suffix"), None))
            attr = (next((c for c in suf.children if c.type == "simple_identifier"), None)
                    if suf is not None else None)
            if tgt is not None and attr is not None:
                return (_node_text(tgt, src) in ("self", "cls", "this")
                        and _node_text(attr, src) == func_name)
            return False
        if fn.type in ("attribute", "member_expression", "field_expression",
                       "selector_expression"):
            obj = fn.child_by_field_name("object") or fn.child_by_field_name("operand")
            attr = (fn.child_by_field_name("attribute") or fn.child_by_field_name("property")
                    or fn.child_by_field_name("field"))
            if obj is not None and attr is not None:
                return (_node_text(obj, src) in ("self", "cls", "this")
                        and _node_text(attr, src) == func_name)
        return False

    def visit_if(node, nesting, as_elseif):
        # wrapper-style（Py/TS/JS/TSX/Rust）。靠 field 名 consequence 認 then-body：block 或無大括號單語句
        # （TS `if(x) for(){}`）皆 +層——對齊 visit_if_field/incr_nest 語意（對抗 review 修「無括號漏增層＝game 向量」）。
        nonlocal total
        total += 1 if as_elseif else (1 + nesting)
        cur = node.walk()
        if not cur.goto_first_child():
            return
        while True:
            c = cur.node
            ct = c.type
            fld = cur.field_name
            if ct in else_t:
                visit_else(c, nesting)        # 平級（不繼承 then-body 的層）
            elif ct in elif_t:
                visit_elif(c, nesting)        # 平級（Python）
            elif fld == "consequence":
                visit(c, nesting + 1)         # then body 增層（block 或無大括號單語句）
            elif c.is_named:
                visit(c, nesting)             # condition / 其他（boolean run / 遞迴）
            if not cur.goto_next_sibling():
                break

    def visit_elif(node, nesting):
        nonlocal total
        total += 1                            # B1 無 B3
        cur = node.walk()
        if not cur.goto_first_child():
            return
        while True:
            c = cur.node
            if cur.field_name == "consequence":
                visit(c, nesting + 1)         # elif body 增層
            elif c.is_named:
                visit(c, nesting)             # condition
            if not cur.goto_next_sibling():
                break

    def visit_else(node, nesting):
        nonlocal total
        p = node.parent
        # else 的合法 if-like parent＝if（含 Ruby unless）或 elsif（Ruby else 的 parent 可能是 elsif）；
        # 否則（for/while/try/begin/case 的 else）→ 透明（Py for-else、Ruby case-else 等）。
        if p is not None and p.type not in if_types and p.type not in elif_t:
            for c in node.children:
                visit(c, nesting)
            return
        inner_if = next((c for c in node.children if c.type in if_types), None)
        if inner_if is not None:              # else if（展平：平級、無 B3；Rust=if_expression）
            visit_if(inner_if, nesting, as_elseif=True)
        else:                                 # 純 else：+1、body 增層（block 或無大括號單語句皆 +層）
            total += 1
            for c in node.children:
                if c.is_named:
                    visit(c, nesting + 1)

    def _unwrap_elseif(node):
        # alternative field 是否為 else-if：Go/Java/C# 直接指 if；Kotlin 的 else-if 是
        # control_structure_body 包單一 if_expression（多一層 wrapper，probe 坐實）→ 剝開取內層 if。
        # control_structure_body 是 Kotlin 專屬節點、Go/Java/C# 不產生 → 對它們零影響。
        if node.type in if_types:
            return node
        if node.type == "control_structure_body":
            named = [c for c in node.children if c.is_named]
            if len(named) == 1 and named[0].type in if_types:
                return named[0]
        return None

    def visit_if_field(node, nesting, as_elseif):
        # field-style else-if（Go/Java/C#/Kotlin）：if.alternative field 指 if（else-if）或 block（純 else），
        # 無 else_clause/elif_clause wrapper。靠 field 名 consequence/alternative 區分 then/else（probe 證跨語言一致）。
        nonlocal total
        total += 1 if as_elseif else (1 + nesting)
        cur = node.walk()
        if not cur.goto_first_child():
            return
        while True:
            child = cur.node
            fld = cur.field_name
            if fld == "consequence":
                visit(child, nesting + 1)             # then body 增層
            elif fld == "alternative":
                inner_if = _unwrap_elseif(child)
                if inner_if is not None:              # else-if：平級、+1 無 B3
                    visit_if_field(inner_if, nesting, as_elseif=True)
                else:                                 # 純 else（block 或無大括號單語句皆 +1）：body 增層
                    total += 1                        # ⚠ Go/Java/C# 允許 `else stmt;` 無 block，仍須 +1
                    visit(child, nesting + 1)
            elif child.is_named:
                visit(child, nesting)                 # condition / initializer（抓 boolean run / 遞迴）
            if not cur.goto_next_sibling():
                break

    def visit_if_swift(node, nesting, as_elseif):
        # Swift 客製：then-body 是無 field 的 statements、else 是 marker token 節點、
        # else-if/純-else body 是 else 的 sibling（probe 坐實）。靠 seen_else flag 區分 then/else-body。
        nonlocal total
        total += 1 if as_elseif else (1 + nesting)
        seen_else = False
        for c in node.children:
            if c.type in else_t:                       # else marker（型別 else）
                seen_else = True
                continue
            if not c.is_named:
                continue
            if not seen_else:
                if c.type == "statements":             # then-body（無 field 名）增層
                    visit(c, nesting + 1)
                else:                                  # condition / 其他（boolean run / 遞迴）
                    visit(c, nesting)
            elif c.type in if_types:                   # else-if（平級、+1 無 B3）
                visit_if_swift(c, nesting, as_elseif=True)
            else:                                      # 純 else body（statements）：+1、body 增層
                total += 1
                visit(c, nesting + 1)

    def visit(node, nesting):
        nonlocal total
        t = node.type
        if _dbg:
            sys.stderr.write(f"[cog] {'. ' * nesting}{t} n={nesting} tot_in={total}\n")

        if not node.is_named:
            # keyword token 與節點型別撞名（Ruby while/until/for/case/unless/if 的 keyword token 之 type
            # ＝while/until/...＝控制流節點型別）→ 不可計分，否則 incr_nest/if_types 對 token 重複 +1。
            # ⚠ symbols.walk v0.11.0 抽符號踩過同坑、同解（is_named 過濾）。
            return

        if t in if_types:
            p = node.parent
            if if_style == "field":
                # field-style（Go/Java/C#/Kotlin）：else-if 內層 if＝parent if 的 alternative → 已由 visit_if_field 處理
                if p is not None and p.type in if_types:
                    return
                visit_if_field(node, nesting, as_elseif=False)
            elif if_style == "swift":
                # Swift：else-if 的內層 if_statement 是 outer if_statement 的直接 child（else 的 sibling）→
                # parent 是 if_statement 時已由 visit_if_swift 處理、skip（巢狀 if 的 parent 是 statements、不 skip）
                if p is not None and p.type in if_types:
                    return
                visit_if_swift(node, nesting, as_elseif=False)
            else:
                # wrapper-style（Py/TS/JS/TSX/Rust/C/C++/Ruby）：else-if 內層 if 在 else_clause/elsif 內 → 已由 visit_else 處理
                if p is not None and p.type in else_t:
                    return
                visit_if(node, nesting, as_elseif=False)
            return
        if t in else_t:
            visit_else(node, nesting)
            return
        if t in elif_t:
            visit_elif(node, nesting)
            return
        if t in transparent:
            for c in node.children:
                visit(c, nesting)
            return
        if t in incr_nest:
            total += 1 + nesting
            for c in node.children:
                # loop 的 else（for-else/while-else）是兄弟層、不繼承 loop body 巢狀深度（對抗 review MEDIUM）
                visit(c, nesting if c.type in else_t else nesting + 1)
            return
        if t in nest_only:
            for c in node.children:
                visit(c, nesting + 1)
            return
        if t in comp_for:
            total += 1 + nesting
            for c in node.children:
                visit(c, nesting + 1)
            return
        if t in comp_if:
            total += 1
            for c in node.children:
                visit(c, nesting)
            return
        if t in boolean:
            if is_logical(node):
                if bool_type_ops is not None:
                    # Kotlin/Swift：&&/|| 是不同節點型別，用 is_bool_root 找最外層（穿祖先防 double-count）
                    if is_bool_root(node):
                        total += count_bool_runs(node)
                else:
                    p = node.parent
                    if not (p is not None and is_logical(p)):
                        total += count_bool_runs(node)   # 只在最外層邏輯節點算一次
            for c in node.children:
                visit(c, nesting)
            return
        if t in labeled_jump:
            if is_labeled(node):
                total += 1
            # 繼續遍歷 children：Kotlin jump_expression / Swift control_transfer_statement 統一涵蓋 return，
            # 其 value 表達式（return f(n-1) 的遞迴 call、return x>0?1:0 的 ternary）須照算（非 return 即漏）。
            for c in node.children:
                visit(c, nesting)
            return
        if t in call_t:
            if func_name and is_direct_recursion(node):
                total += 1
            for c in node.children:
                visit(c, nesting)
            return

        for c in node.children:
            visit(c, nesting)

    try:
        visit(body, 0)
    except RecursionError:
        # 超深 AST（罕見 autogen / 超長布林鏈 / 深 method chain）打爆 Python 堆疊 → 誠實回 None
        # （UNKNOWN），不炸、也不讓上游 engine 裸 except 靜默吞掉整檔指紋（對抗 review CRITICAL）
        return None
    return total

def is_logical(n) -> bool:
    if bool_type_ops is not None:
        return n.type in bool_type_ops
    return n.type in boolean and _op_text(n, src) in bool_ops

def is_bool_root(n) -> bool:
    # 是否為一個布林表達式的最外層 logical 節點（往上若遇另一個 logical 祖先＝非根）。
    # bool_type_ops 語言（Kotlin/Swift）用此判定，避免 grammar 把 a&&b||c 拆成 conjunction/disjunction
    # 多節點各自獨立觸發而 double-count（尤其 Swift 運算子優先級畸形把 logical 埋在 comparison 下）。
    p = n.parent
    while p is not None:
        if is_logical(p):
            return False
        p = p.parent
    return True

def count_bool_runs(node) -> int:
    """連續邏輯運算子：中序收集 operator，數「相鄰不同」的 run 數（a&&b||c=2）。"""
    ops: list[str] = []

    if bool_type_ops is not None:
        # Kotlin/Swift：&&/|| 是不同節點型別、operand 無 left/right field（用位置 named children）；
        # 穿過非 logical 中間層（Swift grammar 運算子優先級畸形會把 logical 埋在 comparison 之下）。
        def collect(n):
            kids = [c for c in n.children if c.is_named]
            if n.type in bool_type_ops:
                if kids:
                    collect(kids[0])
                ops.append(bool_type_ops[n.type])
                for kk in kids[1:]:
                    collect(kk)
            else:
                for kk in kids:
                    collect(kk)
    else:
        def collect(n):
            if is_logical(n):
                left = n.child_by_field_name("left")
                right = n.child_by_field_name("right")
                if left is not None:
                    collect(left)
                ops.append(_op_text(n, src))
                if right is not None:
                    collect(right)

    collect(node)
    if not ops:
        return 0
    runs = 1
    for i in range(1, len(ops)):
        if ops[i] != ops[i - 1]:
            runs += 1
    return runs

def collect(n):
    kids = [c for c in n.children if c.is_named]
    if n.type in bool_type_ops:
        if kids:
            collect(kids[0])
        ops.append(bool_type_ops[n.type])
        for kk in kids[1:]:
            collect(kk)
    else:
        for kk in kids:
            collect(kk)

def collect(n):
    if is_logical(n):
        left = n.child_by_field_name("left")
        right = n.child_by_field_name("right")
        if left is not None:
            collect(left)
        ops.append(_op_text(n, src))
        if right is not None:
            collect(right)

def is_labeled(node) -> bool:
    # 帶 label 才算（裸 break/continue 不算）；各語言 label child 型別不同（per-spec）。
    # jump_keywords（Swift）：control_transfer_statement 統一 continue/break/return，須第一個 child
    # （keyword token）∈ jump_keywords 才算（防 `return x` 的 simple_identifier result 誤判 label）。
    if jump_keywords is not None:
        kids = node.children
        if not kids or kids[0].type not in jump_keywords:
            return False
    return any(c.type in label_child_types for c in node.children)

def is_direct_recursion(call_node) -> bool:
    # 直接遞迴：裸 identifier==func_name，或 self/cls/this.<func_name>；
    # ⛔ 跨物件同名方法 obj.foo() 於名為 foo 的函數內不算（對抗 review MEDIUM 收緊誤判）
    if callee_field is not None:
        fn = call_node.child_by_field_name(callee_field)
    else:
        # Kotlin/Swift call_expression 無 callee field → callee＝第一個 named child
        # （裸呼叫=simple_identifier；member 呼叫=navigation_expression、走下方 navigation 分支）
        fn = next((c for c in call_node.children if c.is_named), None)
        # Swift 算術/比較外包（n * fact(n-1)）：callee 是 binary expression → 下鑽最末 operand 取真 callee
        seen = 0
        while fn is not None and fn.type in _BINARY_CALLEE_WRAP and seen < 8:
            seen += 1
            rhs = fn.child_by_field_name("rhs")
            if rhs is None:
                named = [c for c in fn.children if c.is_named]
                rhs = named[-1] if named else None
            fn = rhs
    if fn is None:
        return False
    if fn.type in _IDENT_TYPES:
        # 有 receiver/object 且非 self/this/cls → 跨物件同名、不算（Java/C# object、Ruby receiver）
        cobj = (call_node.child_by_field_name("object")
                or call_node.child_by_field_name("receiver"))
        if cobj is not None and _node_text(cobj, src) not in ("self", "cls", "this"):
            return False
        return _node_text(fn, src) == func_name
    if fn.type == "navigation_expression":
        # Kotlin/Swift member 呼叫 this.f()/self.f()：navigation_expression
        #   Kotlin（無 field）：[this_expression/identifier, navigation_suffix > simple_identifier]
        #   Swift（有 field）：target field（self_expression）、suffix field（navigation_suffix > simple_identifier）
        tgt = (fn.child_by_field_name("target")
               or next((c for c in fn.children if c.is_named), None))
        suf = (fn.child_by_field_name("suffix")
               or next((c for c in fn.children if c.type == "navigation_suffix"), None))
        attr = (next((c for c in suf.children if c.type == "simple_identifier"), None)
                if suf is not None else None)
        if tgt is not None and attr is not None:
            return (_node_text(tgt, src) in ("self", "cls", "this")
                    and _node_text(attr, src) == func_name)
        return False
    if fn.type in ("attribute", "member_expression", "field_expression",
                   "selector_expression"):
        obj = fn.child_by_field_name("object") or fn.child_by_field_name("operand")
        attr = (fn.child_by_field_name("attribute") or fn.child_by_field_name("property")
                or fn.child_by_field_name("field"))
        if obj is not None and attr is not None:
            return (_node_text(obj, src) in ("self", "cls", "this")
                    and _node_text(attr, src) == func_name)
    return False

def visit_if(node, nesting, as_elseif):
    # wrapper-style（Py/TS/JS/TSX/Rust）。靠 field 名 consequence 認 then-body：block 或無大括號單語句
    # （TS `if(x) for(){}`）皆 +層——對齊 visit_if_field/incr_nest 語意（對抗 review 修「無括號漏增層＝game 向量」）。
    nonlocal total
    total += 1 if as_elseif else (1 + nesting)
    cur = node.walk()
    if not cur.goto_first_child():
        return
    while True:
        c = cur.node
        ct = c.type
        fld = cur.field_name
        if ct in else_t:
            visit_else(c, nesting)        # 平級（不繼承 then-body 的層）
        elif ct in elif_t:
            visit_elif(c, nesting)        # 平級（Python）
        elif fld == "consequence":
            visit(c, nesting + 1)         # then body 增層（block 或無大括號單語句）
        elif c.is_named:
            visit(c, nesting)             # condition / 其他（boolean run / 遞迴）
        if not cur.goto_next_sibling():
            break

def visit_elif(node, nesting):
    nonlocal total
    total += 1                            # B1 無 B3
    cur = node.walk()
    if not cur.goto_first_child():
        return
    while True:
        c = cur.node
        if cur.field_name == "consequence":
            visit(c, nesting + 1)         # elif body 增層
        elif c.is_named:
            visit(c, nesting)             # condition
        if not cur.goto_next_sibling():
            break

def _unwrap_elseif(node):
    # alternative field 是否為 else-if：Go/Java/C# 直接指 if；Kotlin 的 else-if 是
    # control_structure_body 包單一 if_expression（多一層 wrapper，probe 坐實）→ 剝開取內層 if。
    # control_structure_body 是 Kotlin 專屬節點、Go/Java/C# 不產生 → 對它們零影響。
    if node.type in if_types:
        return node
    if node.type == "control_structure_body":
        named = [c for c in node.children if c.is_named]
        if len(named) == 1 and named[0].type in if_types:
            return named[0]
    return None

def visit(node, nesting):
    nonlocal total
    t = node.type
    if _dbg:
        sys.stderr.write(f"[cog] {'. ' * nesting}{t} n={nesting} tot_in={total}\n")

    if not node.is_named:
        # keyword token 與節點型別撞名（Ruby while/until/for/case/unless/if 的 keyword token 之 type
        # ＝while/until/...＝控制流節點型別）→ 不可計分，否則 incr_nest/if_types 對 token 重複 +1。
        # ⚠ symbols.walk v0.11.0 抽符號踩過同坑、同解（is_named 過濾）。
        return

    if t in if_types:
        p = node.parent
        if if_style == "field":
            # field-style（Go/Java/C#/Kotlin）：else-if 內層 if＝parent if 的 alternative → 已由 visit_if_field 處理
            if p is not None and p.type in if_types:
                return
            visit_if_field(node, nesting, as_elseif=False)
        elif if_style == "swift":
            # Swift：else-if 的內層 if_statement 是 outer if_statement 的直接 child（else 的 sibling）→
            # parent 是 if_statement 時已由 visit_if_swift 處理、skip（巢狀 if 的 parent 是 statements、不 skip）
            if p is not None and p.type in if_types:
                return
            visit_if_swift(node, nesting, as_elseif=False)
        else:
            # wrapper-style（Py/TS/JS/TSX/Rust/C/C++/Ruby）：else-if 內層 if 在 else_clause/elsif 內 → 已由 visit_else 處理
            if p is not None and p.type in else_t:
                return
            visit_if(node, nesting, as_elseif=False)
        return
    if t in else_t:
        visit_else(node, nesting)
        return
    if t in elif_t:
        visit_elif(node, nesting)
        return
    if t in transparent:
        for c in node.children:
            visit(c, nesting)
        return
    if t in incr_nest:
        total += 1 + nesting
        for c in node.children:
            # loop 的 else（for-else/while-else）是兄弟層、不繼承 loop body 巢狀深度（對抗 review MEDIUM）
            visit(c, nesting if c.type in else_t else nesting + 1)
        return
    if t in nest_only:
        for c in node.children:
            visit(c, nesting + 1)
        return
    if t in comp_for:
        total += 1 + nesting
        for c in node.children:
            visit(c, nesting + 1)
        return
    if t in comp_if:
        total += 1
        for c in node.children:
            visit(c, nesting)
        return
    if t in boolean:
        if is_logical(node):
            if bool_type_ops is not None:
                # Kotlin/Swift：&&/|| 是不同節點型別，用 is_bool_root 找最外層（穿祖先防 double-count）
                if is_bool_root(node):
                    total += count_bool_runs(node)
            else:
                p = node.parent
                if not (p is not None and is_logical(p)):
                    total += count_bool_runs(node)   # 只在最外層邏輯節點算一次
        for c in node.children:
            visit(c, nesting)
        return
    if t in labeled_jump:
        if is_labeled(node):
            total += 1
        # 繼續遍歷 children：Kotlin jump_expression / Swift control_transfer_statement 統一涵蓋 return，
        # 其 value 表達式（return f(n-1) 的遞迴 call、return x>0?1:0 的 ternary）須照算（非 return 即漏）。
        for c in node.children:
            visit(c, nesting)
        return
    if t in call_t:
        if func_name and is_direct_recursion(node):
            total += 1
        for c in node.children:
            visit(c, nesting)
        return

    for c in node.children:
        visit(c, nesting)

def _get_watch_mgr():
    global _WATCH_MGR
    if _WATCH_MGR is None:
        _WATCH_MGR = watcher.WatchManager(get_logger())
    return _WATCH_MGR

def _port() -> int:
    """固定 port 8790，可由環境變數 CODESEXTANT_PORT 覆寫（對齊 PoC t5 與設計 §3①）。"""
    try:
        return int(os.environ.get("CODESEXTANT_PORT", str(DEFAULT_PORT)))
    except ValueError:
        return DEFAULT_PORT

def _health_brand_ok(data: dict) -> bool:
    """brand 比對：service 是 codesextant 或產品名 codesextant 才算「我們的 daemon」。
    （別的程式剛好佔同一 port、回別的 JSON 一律不算，對齊 PoC t5 + memory:
     brain_watchdog 只檢 TCP 半殘 → 要檢 /health HTTP 回應。）"""
    return isinstance(data, dict) and data.get("service") in (SERVICE_NAME, "codesextant")

def http_ping(host: str = HOST, port: int | None = None, timeout: float = 0.6) -> dict | None:
    """嚴格探活：打 GET /health，回傳解析後的 dict（brand 對才回，否則 None）。
    回 dict 比回 bool 多給呼叫者 pid 等資訊（ensure 拿來證明單例）。"""
    port = port or _port()
    try:
        with urllib.request.urlopen(f"http://{host}:{port}/health", timeout=timeout) as r:
            data = json.loads(r.read().decode("utf-8"))
        return data if _health_brand_ok(data) else None
    except Exception:
        return None

def is_port_listening(host: str = HOST, port: int | None = None, timeout: float = 0.3) -> bool:
    """裸 TCP 探活（只看 port 有沒有人 listen，不看 brand）。
    僅供診斷/stop 判斷用——單例判定一律用 http_ping（嚴格 brand）。"""
    port = port or _port()
    try:
        with socket.create_connection((host, port), timeout=timeout):
            return True
    except OSError:
        return False

def _require_project(project: str | None):
    """所有資料端點都要 project（=repo 絕對路徑）。缺 → 400。"""
    if not project:
        raise _HttpError(400, "缺少必要參數 project（= repo 絕對路徑）")
    # queue 3：查過的專案自動掛 file-watcher（冪等；watchdog 缺/關閉則靜默 no-op）
    try:
        _get_watch_mgr().ensure_watch(project)
    except Exception:
        pass
    return project

class _HttpError(Exception):
    """帶 HTTP 狀態碼的受控錯誤（→ 端點回對應 code + 中文訊息，不是 500）。"""
    def __init__(self, code: int, msg: str):
        super().__init__(msg)
        self.code = code
        self.msg = msg

def _engine_pkg_version():
    # 絕對 import：daemon 被 ensure 以「檔路徑」detached 拉起時是 __main__（無 package
    # 脈絡），相對 import 會失敗。此時 sys.path 已補過 parent.parent，codesextant 必可 import。
    try:
        from codesextant import __version__ as v  # type: ignore
        return v
    except Exception:
        return None

def _ep_get_symbols(parsed, body):
    project = _require_project(_q(parsed, "project"))
    file = _q(parsed, "file")
    return 200, engine.get_symbols(project, file=file)

def _ep_find_references(parsed, body):
    body = body or {}
    project = _require_project(body.get("project"))
    symbol = body.get("symbol")
    if not symbol:
        raise _HttpError(400, "find_references 缺少必要參數 symbol")
    return 200, engine.find_references(
        project, symbol,
        def_path=body.get("def_path"),
        src_root=body.get("src_root"),
        include_low_confidence=body.get("include_low_confidence", True),
        persist=body.get("persist", True),
    )

def _ep_get_map(parsed, body):
    project = _require_project(_q(parsed, "project"))
    budget_raw = _q(parsed, "budget", "2000")
    try:
        budget = int(budget_raw)
    except (TypeError, ValueError):
        raise _HttpError(400, f"budget 必須是整數，收到 '{budget_raw}'")
    # queue 4：query-aware focus（逗號分隔；呼叫端顯式傳「在改/在問的符號/檔」）
    fsy = _q(parsed, "focus_symbols")
    ffi = _q(parsed, "focus_files")
    fs = [x for x in fsy.split(",") if x] if fsy else None
    ff = [x for x in ffi.split(",") if x] if ffi else None
    return 200, engine.get_map(project, token_budget=budget, focus_symbols=fs, focus_files=ff)

def _ep_reindex(parsed, body):
    body = body or {}
    project = _require_project(body.get("project"))
    force = bool(body.get("force", False))
    return 200, engine.index_project(project, force=force)

def _ep_status(parsed, body):
    project = _require_project(_q(parsed, "project"))
    # 坑7-1：git freshness 會 spawn git 子進程，預設不查（避免不設防 GET 被惡意網頁
    # no-cors 觸發 spawn 風暴）；面板/客戶端要新鮮度時明確帶 ?fresh=1。
    fresh = str(_q(parsed, "fresh", "") or "").lower() in ("1", "true", "yes", "on")
    return 200, engine.status(project, check_freshness=fresh)

def _ep_projects(parsed, body):
