def _send_json(self, code: int, obj: dict):
    body = json.dumps(obj, ensure_ascii=False, default=str).encode("utf-8")
    self.send_response(code)
    self.send_header("Content-Type", "application/json; charset=utf-8")
    self.send_header("Content-Length", str(len(body)))
    self.end_headers()
    try:
        self.wfile.write(body)
    except (BrokenPipeError, ConnectionResetError):
        pass

def _send_html(self, code: int, html: str):
    body = html.encode("utf-8")
    self.send_response(code)
    self.send_header("Content-Type", "text/html; charset=utf-8")
    self.send_header("Content-Length", str(len(body)))
    self.end_headers()
    try:
        self.wfile.write(body)
    except (BrokenPipeError, ConnectionResetError):
        pass

def _read_body(self) -> dict:
    length = int(self.headers.get("Content-Length", 0) or 0)
    if length <= 0:
        return {}
    raw = self.rfile.read(length)
    if not raw:
        return {}
    try:
        return json.loads(raw.decode("utf-8"))
    except json.JSONDecodeError as exc:
        raise _HttpError(400, f"請求 body 不是合法 JSON：{exc}")

def _summ(result: dict) -> str:
    """從端點回傳摘出幾個關鍵欄位寫 log（避免整包刷爆 log）。"""
    if not isinstance(result, dict):
        return ""
    keys = ("count", "indexed", "skipped", "symbols_total", "high_confidence",
            "indexed_files", "symbols", "name_match_file_count", "就緒")
    bits = []
    for k in keys:
        if k in result:
            v = result[k]
            v = len(v) if isinstance(v, list) else v
            bits.append(f"{k}={v}")
    return " ".join(bits)

def serve(port: int | None = None):
    """前景跑 HTTP server（ensure 會 detached 背景呼叫這個）。"""
    port = port or _port()
    lg = get_logger()
    try:
        srv = ThreadingHTTPServer((HOST, port), _Handler)
    except OSError as exc:
        lg.error("daemon 啟動失敗（port %d 可能已被占用）：%s", port, exc)
        raise
    lg.info("daemon 啟動 listening http://%s:%d  service=%s  log=%s",
            HOST, port, SERVICE_NAME, _log_path())
    print(f"[codesextant daemon] listening http://{HOST}:{port} "
          f"(pid={os.getpid()}, service={SERVICE_NAME})")
    # queue 3：對已索引且路徑還在的專案掛 file-watcher（主動增量、地圖永遠新鮮）
    if watcher.watch_enabled():
        try:
            mgr = _get_watch_mgr()
            for p in storage.list_indexed_projects():
                if p.get("path_exists") and p.get("repo_path"):
                    mgr.ensure_watch(p["repo_path"])
        except Exception as exc:
            lg.warning("watcher 初始掛載略過：%s", exc)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        lg.info("daemon 收到中斷，準備關閉")
    finally:
        srv.server_close()
        try:
            _get_watch_mgr().stop_all()
        except Exception:
            pass
        lg.info("daemon 已關閉")

def stop_running(port: int | None = None) -> dict:
    """關掉本機 daemon（驗證清殘留 / 重啟用）。

    精準殺：只用 /health 拿到的「我們自己 daemon 的 pid」+ 確認 Name=python，
    ⛔不用 CommandLine match 腳本名（memory: 會殺到自己的 shell exit255）。
    """
    port = port or _port()
    lg = get_logger()
    alive = http_ping(port=port)
    if alive is None:
        lg.info("stop：port %d 上沒有我們的 daemon（無需關閉）", port)
        return {"action": "not-running", "port": port}
    pid = alive.get("pid")
    if not pid:
        return {"action": "no-pid", "port": port}
    try:
        if os.name == "nt":
            # taskkill /PID /F：按 PID 精準殺單一進程（不靠腳本名 match）
            subprocess.run(["taskkill", "/PID", str(pid), "/F"],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                           check=False)
        else:
            os.kill(int(pid), 15)
        lg.info("stop：已送出關閉 daemon pid=%d（port=%d）", pid, port)
    except Exception as exc:
        lg.exception("stop：關閉 pid=%s 失敗：%s", pid, exc)
        return {"action": "kill-failed", "pid": pid, "port": port, "error": str(exc)}

    # 確認 port 釋放
    for _ in range(15):
        if http_ping(port=port) is None and not is_port_listening(port=port):
            lg.info("stop：daemon 已停、port %d 已釋放", port)
            return {"action": "stopped", "pid": pid, "port": port, "port_released": True}
        time.sleep(0.2)
    return {"action": "stopped", "pid": pid, "port": port, "port_released": False}

def _lint_timeout(default: float) -> float:
    try:
        v = float(_env("CODESEXTANT_DEADCODE_LINT_TIMEOUT", ""))
        return v if v > 0 else default
    except ValueError:
        return default

def _run_ruff_f401(target: str) -> dict:
    """ruff check --select F401（未使用 import）。回 {available, findings|reason}。

    ruff 是事實標準的 Python linter，F401=`imported but unused`，正確處理副作用 import
    （`# noqa`）、`__all__` re-export、TYPE_CHECKING 區塊——遠勝自造 AST 差集。
    """
    if shutil.which("ruff") is None:
        return {"available": False,
                "reason": "未裝 ruff（pip install ruff 後即可偵測 Python 未使用 import）"}
    kw: dict = {"capture_output": True, "timeout": _lint_timeout(60)}
    if os.name == "nt":
        kw["creationflags"] = _CREATE_NO_WINDOW
    try:
        proc = subprocess.run(
            ["ruff", "check", "--select", "F401", "--output-format", "json", target], **kw)
    except (subprocess.TimeoutExpired, OSError) as exc:
        return {"available": False, "reason": f"ruff 執行失敗：{exc}"}
    # ruff exit 1 = 有 lint 命中（正常），0 = 無命中；>1 = 真錯（config/路徑問題）
    if proc.returncode not in (0, 1):
        err = proc.stderr.decode("utf-8", "replace")[:200] if proc.stderr else ""
        return {"available": False, "reason": f"ruff 退出碼 {proc.returncode}：{err}"}
    try:
        data = json.loads(proc.stdout.decode("utf-8", "replace") or "[]")
    except json.JSONDecodeError:
        return {"available": False, "reason": "ruff 輸出非 JSON（版本過舊？需支援 --output-format json）"}
    findings = []
    for d in data:
        if not isinstance(d, dict):
            continue
        loc = d.get("location") or {}
        findings.append({
            "path": d.get("filename"),
            "line": loc.get("row"),
            "code": d.get("code"),
            "message": d.get("message"),
        })
    return {"available": True, "findings": findings}

def _run_eslint_unused(target: str, root: str) -> dict:
    """eslint --format json，過濾 no-unused-vars / unused-imports 規則命中。

    ⚠ eslint 需專案自帶 config（規則因專案而異，⛔ 不臆測）；無 config / 無 eslint →
    回不可用，呼叫端據此標 UNKNOWN_NO_LINTER（誠實「我不知道」，不亂判）。
    """
    if shutil.which("eslint") is None and shutil.which("npx") is None:
        return {"available": False, "reason": "未裝 eslint/npx（無法偵測 TS/JS 未使用 import）"}
    has_cfg = any(os.path.isfile(os.path.join(root, c)) for c in _ESLINT_CONFIGS)
    if not has_cfg:
        return {"available": False, "reason": "專案無 eslint config，跳過（不臆測 lint 規則）"}
    if shutil.which("eslint"):
        cmd = ["eslint", "--format", "json", target]
    else:
        cmd = ["npx", "--no-install", "eslint", "--format", "json", target]
    kw: dict = {"capture_output": True, "timeout": _lint_timeout(120), "cwd": root}
    if os.name == "nt":
        kw["creationflags"] = _CREATE_NO_WINDOW
    try:
        proc = subprocess.run(cmd, **kw)
    except (subprocess.TimeoutExpired, OSError) as exc:
        return {"available": False, "reason": f"eslint 執行失敗：{exc}"}
    try:
        data = json.loads(proc.stdout.decode("utf-8", "replace") or "[]")
    except json.JSONDecodeError:
        return {"available": False, "reason": "eslint 輸出非 JSON（config 可能有誤或非 lint 模式）"}
    findings = []
    for f in data if isinstance(data, list) else []:
        if not isinstance(f, dict):
            continue
        for m in f.get("messages", []) or []:
            rule = (m.get("ruleId") or "")
            if "no-unused-vars" in rule or "unused-imports" in rule:
                findings.append({
                    "path": f.get("filePath"),
                    "line": m.get("line"),
                    "code": rule,
                    "message": m.get("message"),
                })
    return {"available": True, "findings": findings}

def detect_unused_imports(target: str, *, root: str, lang: str | None = None) -> dict:
    """偵測未使用 import——auto 依語言選 ruff(Python)/eslint(TS/JS)。

    回 dict：
      可用 → {available:True, linter, findings:[{path,line,code,message}]}
      不可用 → {available:False, linter, verdict:"UNKNOWN_NO_LINTER", reason, findings:[]}
      關閉 → {available:False, linter:None, reason:"已關閉", findings:[]}
    ⛔ 不可用一律 UNKNOWN_NO_LINTER（誠實），絕不退化成自造 AST 假陽性。
    """
    mode = linter_mode()
    if mode == "off":
        return {"available": False, "linter": None, "findings": [],
                "reason": "已關閉（CODESEXTANT_DEADCODE_LINTER=off）"}
    is_dir = os.path.isdir(target)
    tlang = lang if lang else (None if is_dir else symbols.language_for_file(target))
    use = mode
    if mode == "auto":
        if tlang in ("typescript", "tsx", "javascript"):
            use = "eslint"
        elif tlang in ("python", None):   # None = 目錄掃描，沿用既有 ruff（限 Python）
            use = "ruff"
        else:
            # 2026-06-22：其他語言（C#/Java/C/C++/Lua/Ruby/PHP/Bash/Kotlin/Swift）無對應
            # unused-import linter（ruff 限 Python、eslint 限 TS/JS）→ 誠實 UNKNOWN，⛔ 不硬跑 ruff
            # 對 .cs/.java 等（會回無檔誤導）。對齊死碼層「寧 UNKNOWN 不假陽性」命門。
            return {"available": False, "linter": None, "findings": [],
                    "verdict": "UNKNOWN_NO_LINTER",
                    "reason": f"語言 '{tlang}' 無 unused-import linter（ruff 限 Python、eslint 限 TS/JS）"}
    if use == "ruff":
        r = _run_ruff_f401(target)
    elif use == "eslint":
        r = _run_eslint_unused(target, root)
    else:
        return {"available": False, "linter": use, "findings": [],
                "verdict": "UNKNOWN_NO_LINTER", "reason": f"未知 linter mode={use}"}
    if r.get("available"):
        return {"available": True, "linter": use, "findings": r["findings"]}
    return {"available": False, "linter": use, "findings": [],
            "verdict": "UNKNOWN_NO_LINTER", "reason": r.get("reason")}

_ENTRYPOINT_BARE_DECORATORS = (
    "@task", "@fixture", "@event", "@shared_task", "@callback", "@command",
)

def _decorator_hits(deco: str) -> bool:
    d = deco.lstrip()
    if _ENTRYPOINT_DECORATOR_RE.match(d):
        return True
    head = d.split("(", 1)[0].strip()
    return any(head == b for b in _ENTRYPOINT_BARE_DECORATORS)

def entry_point_func_names(root: str) -> set[str]:
    """解析專案根 pyproject.toml 的 [project.scripts]/[project.gui-scripts]，回 console_scripts
    指向的 func 名集合（"pkg.cli:main" → "main"）。

    紅隊 L3-HIGH：console_scripts 入口是安裝後 wrapper 反射呼叫、源碼裡無人提及它的名 →
    名稱級 external usage 必為 0 → find_unwired 不豁免就會把幾乎每個 CLI 主入口誤報未接線。
    env CODESEXTANT_SCAN_ENTRYPOINTS=0/false/no/off 關閉（預設 on）。讀檔失敗/無 pyproject → 空集合。
    """
    if os.environ.get("CODESEXTANT_SCAN_ENTRYPOINTS", "").lower() in ("0", "false", "no", "off"):
        return set()
    pyproject = os.path.join(root, "pyproject.toml")
    if not os.path.isfile(pyproject):
        return set()
    try:
        import tomllib  # Python 3.11+ 標準庫
        with open(pyproject, "rb") as f:
            data = tomllib.load(f)
    except Exception:
        return set()
    funcs: set[str] = set()
    proj = (data.get("project") or {}) if isinstance(data, dict) else {}
    for key in ("scripts", "gui-scripts"):
        for _ep, target in (proj.get(key) or {}).items():
            # target 形如 "pkg.module:func" 或 "pkg.module:obj.method"
            if isinstance(target, str) and ":" in target:
                func = target.split(":", 1)[1].strip().split(".")[0]
                if func:
                    funcs.add(func)
    return funcs

def _has_entrypoint_decorator(source: str, symbol_name: str) -> bool:
    """符號定義（def/class symbol_name）上方連續裝飾器是否含反射入口裝飾器。"""
    lines = source.splitlines()
    pat = re.compile(r"^\s*(?:async\s+)?(?:def|class)\s+" + re.escape(symbol_name) + r"\b")
    for i, ln in enumerate(lines):
        if not pat.match(ln):
            continue
        j = i - 1
        while j >= 0:
            stripped = lines[j].strip()
            if not stripped:           # 允許空行夾在裝飾器間
                j -= 1
                continue
            if stripped.startswith("@"):
                if _decorator_hits(stripped):
                    return True
                j -= 1
                continue
            break                       # 撞到非裝飾器非空行 → 停
    return False

def _in_dunder_all(source: str, symbol_name: str) -> bool:
    """符號是否列在 __all__（顯式公開 API、永不刪）。"""
    m = re.search(r"__all__\s*=\s*[\[\(](.*?)[\]\)]", source, re.S)
    if not m:
        return False
    return re.search(r"['\"]" + re.escape(symbol_name) + r"['\"]", m.group(1)) is not None

def is_entrypoint(path: str, *, symbol_name: str | None = None,
                  source: str | None = None) -> tuple[bool, str | None]:
    """某符號是否屬入口/反射呼叫（→ PUBLIC_API、永不進刪除候選）。

    判定順序：檔名約定 → 使用者額外清單 → （給了 source+symbol）裝飾器 / __all__。
    回 (是否入口, 中文原因)。
    """
    posix = path.replace("\\", "/")
    for pat, reason in _ENTRYPOINT_FILE_PATTERNS:
        if re.search(pat, posix):
            return True, reason
    extra = _env("CODESEXTANT_DEADCODE_ENTRYPOINT_EXTRA", "")
    for frag in extra.split(os.pathsep):
        frag = frag.strip()
        if frag and frag in posix:
            return True, "使用者指定入口（CODESEXTANT_DEADCODE_ENTRYPOINT_EXTRA）"
    if source and symbol_name:
        if _has_entrypoint_decorator(source, symbol_name):
            return True, "帶路由/任務/fixture 裝飾器（框架反射入口）"
        if _in_dunder_all(source, symbol_name):
            return True, "列於 __all__（顯式公開 API）"
    return False, None

def classify_orphan(refs_result: dict | None, *, is_entry: bool,
                    entry_reason: str | None) -> dict:
    """把「某符號的 find_references 結果」分級成 orphan verdict。

    安全閘（兩道，皆「寧 UNKNOWN 不假陽性」）：
      ① engine 不是真解析（jedi/ts-morph）→ UNKNOWN_NO_RESOLVER（紅隊 B2：無引擎不可判可刪）。
      ② 真解析了、但**沒定位到符號定義**（error 或 definition 缺）→ UNKNOWN_UNRESOLVED。
         這條至關重要：high=0 可能是「真沒引用」**也可能是「解析器根本沒定位到定義」**
         （如 jedi 二段式只認 def/class 行、module 級變數賦值 `NAME = ...` 定位不到 → 直接
         error → high=0）。若不擋，module 級常數/變數會被自信誤判 LIKELY_UNUSED（2026-06-19
         序3 實跑 daemon.py SERVICE_NAME/HOST/_ROUTES_GET 假陽性現形）。variable 的真解析待序4。
    只有「真解析 + 有定位到定義 + high=0」才敢給 LIKELY_UNUSED🟡（且仍要人工複核+build）。
    """
    if is_entry:
        return {"verdict": "PUBLIC_API", "icon": _VERDICT_ICON["PUBLIC_API"],
                "reason": entry_reason or "入口/反射呼叫"}
    refs_result = refs_result or {}
    engine = refs_result.get("engine")
    if engine not in ("jedi", "ts-morph"):
        return {"verdict": "UNKNOWN_NO_RESOLVER", "icon": _VERDICT_ICON["UNKNOWN_NO_RESOLVER"],
                "reason": f"無真解析引擎（engine={engine or '無'}），不判定是否可刪"}
    if refs_result.get("error") or not refs_result.get("definition"):
        return {"verdict": "UNKNOWN_UNRESOLVED", "icon": _VERDICT_ICON["UNKNOWN_UNRESOLVED"],
                "reason": ("解析器未定位到此符號定義（如 module 級變數賦值 / 非 def-class 符號），"
                           "high=0 不代表真沒引用 → 不判可刪")}
    high = refs_result.get("high_confidence") or []
    if high:
        # 序4：若全部高信心引用都是 re-export（barrel `export {X} from` / 本檔 `export {X}` 導出、
        # 無真內部消費）→ REEXPORT_ONLY，⛔ 不當真 KEEP（沒人真用）也不誤判 LIKELY_UNUSED
        # （它確實被導出、可能是對外 public API）。jedi（Python）的 high 無 is_reexport 旗標 →
        # all() 為 False → 自然走 KEEP，Python 不受影響。
        if all(h.get("is_reexport") for h in high):
            return {"verdict": "REEXPORT_ONLY", "icon": _VERDICT_ICON["REEXPORT_ONLY"],
                    "reason": (f"{len(high)} 處引用全是 re-export/導出、無真內部消費；"
                               "可能是對外 public API，也可能整條導出鏈皆可刪——請人工複核")}
        real = sum(1 for h in high if not h.get("is_reexport"))
        rx = len(high) - real
        suffix = f"（另 {rx} 處 re-export）" if rx else ""
        return {"verdict": "KEEP", "icon": _VERDICT_ICON["KEEP"],
                "reason": f"{real} 處真消費引用（{engine} 確認）{suffix}"}
    return {"verdict": "LIKELY_UNUSED", "icon": _VERDICT_ICON["LIKELY_UNUSED"],
            "reason": f"{engine} 真解析零高信心引用；請人工複核 + 跑 build 再刪（非自信定論）"}

def _iter_source_files(root: str):
    """掃 root 下所有「支援語言」的原始碼檔（C5：多語言；跳過雜訊目錄）。"""
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in _SKIP_DIRS]
        for fn in filenames:
            if os.path.splitext(fn)[1].lower() in SUPPORTED_EXTENSIONS:
                yield os.path.join(dirpath, fn)

def _env_on(name: str) -> bool:
    """env 旗標解析（統一走 .lower()，避免 =True/=TRUE 被當沒設）。"""
    return os.environ.get(name, "").lower() in ("1", "true", "yes", "on")

def _infer_project_language(root: str, *, sample_cap: int | None = None) -> str | None:
    """坑9：找引用時 symbol 查無候選定義（def_path=None）且 jedi 也找不到定義時，
    取樣專案主語言做 **fallback**（非 override，見 find_references），避免非 Python
    symbol 走名稱比對死路。

    只在主導語言佔比 ≥ 門檻時回該語言（平手/混合不硬選＝回 None 走保守 jedi、誤判成本
    最低）；判不出回 None。開關（L0 鐵律 #6，皆 .lower() 容錯）：
      - CODESEXTANT_INFER_LANG_DISABLED=1/true/yes/on → 回 None（停用）。
      - CODESEXTANT_INFER_LANG_SAMPLE_CAP=<int> → 取樣上限（預設 1000；<=0 表不截斷全掃）。
      - CODESEXTANT_INFER_LANG_MIN_RATIO=<float> → 主導佔比門檻（預設 0.6）。
    """
    if _env_on("CODESEXTANT_INFER_LANG_DISABLED"):
        return None
    if sample_cap is None:
        try:
            sample_cap = int(os.environ.get("CODESEXTANT_INFER_LANG_SAMPLE_CAP", "1000"))
        except ValueError:
            sample_cap = 1000
    try:
        min_ratio = float(os.environ.get("CODESEXTANT_INFER_LANG_MIN_RATIO", "0.6"))
    except ValueError:
        min_ratio = 0.6

    from collections import Counter
    counts: "Counter[str]" = Counter()
    seen = 0
    for fp in _iter_source_files(root):
        lang = symbols.language_for_file(fp)
        if lang:
            counts[lang] += 1
        seen += 1
        if sample_cap > 0 and seen >= sample_cap:
            break
    total = sum(counts.values())
    if total == 0:
        return None
    top_lang, top_n = counts.most_common(1)[0]
    # 主導佔比未達門檻（混合/平手）→ 回 None 走保守 jedi（決定性、誤判成本最低）
    if top_n / total < min_ratio:
        return None
    return top_lang

def _git_head_sha(repo_path: str) -> str | None:
    """坑6：讀 repo 的 git HEAD sha（freshness 比對用）。非 git repo／git 不可用／
    開關關閉 → None。Windows detached daemon 下不彈黑窗（CREATE_NO_WINDOW）。
    開關（L0 鐵律 #6，.lower() 容錯）：CODESEXTANT_GIT_FRESHNESS_DISABLED=1/true/yes/on → None。
    """
    if _env_on("CODESEXTANT_GIT_FRESHNESS_DISABLED"):
        return None
    try:
        import subprocess
        kwargs = {"capture_output": True, "text": True, "timeout": 5}
        if os.name == "nt":
            kwargs["creationflags"] = 0x08000000  # CREATE_NO_WINDOW（detached 不彈黑窗）
        out = subprocess.run(["git", "-C", repo_path, "rev-parse", "HEAD"], **kwargs)
        if out.returncode == 0:
            return out.stdout.strip() or None
    except Exception:
        pass
    return None

def _refs_non_python(root: str, symbol: str, def_path: str | None, lang: str,
                     include_low_confidence: bool) -> dict:
    """非 Python 找引用 dispatch：TS/JS 先試 ts-morph 高信心、不可用 fallback 名稱比對
    （不爆）；其他語言走名稱比對退化（全低信心、誠實標示）。"""
    if lang in ("typescript", "tsx", "javascript"):
        result = references.ts_morph_references(root, symbol, def_path=def_path)
        if result is None:
            result = references.name_match_references(
                root, symbol, def_path=def_path, lang=lang,
                include_low_confidence=include_low_confidence,
            )
        return result
    return references.name_match_references(
        root, symbol, def_path=def_path, lang=lang,
        include_low_confidence=include_low_confidence,
    )

def _refs_reliability(result: dict) -> dict:
    """序6：依 find_references 結果品質自評可靠度 + 給「何時該回去讀原始碼」建議。

    level：high=可直接信任 / medium=部分可信但有盲區、建議補讀 / low=務必讀碼別當定論。
    ⛔ 不管哪一級都**不取代讀碼判斷邏輯對錯**——本工具只看引用關聯、不看語義與業務意圖；
    且靜態解析一律看不到動態/反射/字串拼接的呼叫（這正是最該人工讀碼之處）。
    """
    engine = result.get("engine")
    high = len(result.get("high_confidence") or [])
    low = len(result.get("low_confidence") or [])
    if engine == "name-match":
        return {"level": "low",
                "advice": "純名稱比對（無真 import 解析）——含同名干擾、且看不到動態/反射呼叫；"
                          "務必讀原始碼確認，別把這份清單當完整或精確。"}
    if not result.get("definition"):
        return {"level": "low",
                "advice": "未定位到符號定義（可能拼錯／不在此 repo／是 module 級變數）——"
                          "結果不完整，建議直接讀原始碼確認。"}
    if high == 0 and low == 0:
        return {"level": "medium",
                "advice": "真解析得到零引用——可能真沒人用，也可能是動態/反射/字串拼接呼叫"
                          "（靜態解析一律看不到）；刪改前讀那段碼上下文確認。"}
    if low > high * 3 and low > 5:
        return {"level": "medium",
                "advice": f"低信心({low})遠多於高信心({high})、多為同名干擾；高信心那 {high} 處可信，"
                          "但若你要找的用法不在其中，建議掃一眼低信心或讀原始碼。"}
    return {"level": "high",
            "advice": f"真解析高信心引用 {high} 處、可直接信任省去人肉追引用"
                      "（仍：改簽章/刪除後跑 build 驗證；**邏輯對錯仍需讀碼**）。"}

def _mark_high_importance(path: str, callers: list[dict]) -> list[dict]:
    """標出受影響 caller 中 PageRank 高重要度者（接 get_map top 符號名集合）。

    紅隊 L2-MEDIUM 修正：with_name_edges=False 走輕量路徑——impact/blast-radius 是高頻熱
    路徑，只需「結構中心 top 符號名」過濾 caller，不需名稱級排序精度；舊版每次 impact 都附帶
    觸發一次全 repo 名稱級掃描（實測 5.5x 退化、且該場景 high_importance 常為 0＝零價值）。
    """
    try:
        m = get_map(path, token_budget=3000, with_name_edges=False)
        top_names = {s.get("name") for s in (m.get("symbols") or [])[:30]}
    except Exception:
        top_names = set()
    return [c for c in callers if c.get("name") in top_names]

def _src_of(p: str) -> str:
    if p not in _src_cache:
        try:
            with open(p, "r", encoding="utf-8", errors="replace") as f:
                _src_cache[p] = f.read()
        except OSError:
            _src_cache[p] = ""
    return _src_cache[p]

def _comment_coverage_kinds() -> set[str]:
    raw = os.environ.get("CODESEXTANT_COMMENT_COVERAGE_KINDS", "function,class,method,interface")
    return {k.strip() for k in raw.split(",") if k.strip()}

def _comment_skip_private() -> bool:
    return os.environ.get("CODESEXTANT_COMMENT_COVERAGE_SKIP_PRIVATE", "").lower() not in (
        "0", "false", "no", "off")

def _comment_density_enabled() -> bool:
    return os.environ.get("CODESEXTANT_COMMENT_DENSITY_DISABLED", "").lower() not in (
        "1", "true", "yes", "on")

def get_comments(path: str, file: str | None = None, *, scope: str | None = None,
                 doc_only: bool = False, tag: str | None = None) -> dict:
    """精確過濾取註解（功能 B「只看該看的」，比照 get_symbols）。未索引 → count=0+note 不假裝。"""
    abs_path = os.path.abspath(path)
    db_file = storage.db_path_for(abs_path)
    if not db_file.exists():
        return {"project_key": storage.project_key(abs_path), "count": 0, "comments": [],
                "note": f"專案尚未索引（無 {db_file}）。請先呼叫 index_project。"}
    target = os.path.abspath(file) if file else None
    with storage.ProjectStore.open(abs_path) as store:
        q = ("SELECT path,line,end_line,kind,is_doc,tag,scope,owner_line,text "
             "FROM comments WHERE 1=1")
        p: list = []
        if target:
            q += " AND path=?"; p.append(target)
        if doc_only:
            q += " AND is_doc=1"
        if tag:
            q += " AND tag=?"; p.append(tag.upper())
        if scope is not None:
            q += " AND scope=?"; p.append(scope)
        q += " ORDER BY path,line"
        rows = [dict(r) for r in store.conn.execute(q, p).fetchall()]
        return {"project_key": store.project_key, "file": target,
                "count": len(rows), "comments": rows}

