    "EXACT_DUP": "🟥", "RENAMED_DUP": "🟧", "STRUCTURAL_NEAR": "🟨",
    "CALL_PATTERN_SIM": "🟦", "BOILERPLATE_SUPPRESSED": "⚪", "UNKNOWN_TOO_SMALL": "❔",
}

def _make_dup_group(verdict: str, members: list[dict], similarity, reason: str) -> dict:
    """組一個重複群（jscpd compact 格式：位置+名+信心，⛔不貼原始碼，守唯讀導航圖）。"""
    return {
        "verdict": verdict, "icon": _DUP_VERDICT_ICON[verdict], "similarity": similarity,
        "members": [{"path": m["path"], "line": m["line"], "end_line": m.get("end_line"),
                     "name": m.get("name"), "scope": m.get("scope")} for m in members],
        "representative": members[0].get("name"),
        "node_count": members[0].get("node_count"),
        "reason": reason,
    }

def _in_scope(members) -> bool:
    """scope_file 模式：群至少含一個 target 檔成員才輸出（None=不限、全輸出）。"""
    return (not target) or any(os.path.abspath(m["path"]) == target for m in members)

def render(sections: list[Section], *, budget: int, full: bool = False,
           item_fmt=str, indent: str = "  ") -> list[str]:
    """壓縮 + 渲染成文字行（各分區標題 + 條目 + 麵包屑）。回 list[str]。

    item_fmt：把單個條目轉成顯示字串的函數（預設 str）。空分區（total=0）不印。
    """
    lines: list[str] = []
    for cs in compress(sections, budget=budget, full=full):
        if cs.total == 0:
            continue
        head = f"{indent}{cs.label}：{cs.total} 個"
        if cs.elided:
            head += f"（顯示 {len(cs.shown)}、另 {cs.elided} 省略，--full 看全部）"
        lines.append(head)
        for it in cs.shown:
            lines.append(f"{indent}  {item_fmt(it)}")
    return lines

W = {"dup": float(os.environ.get("CODESEXTANT_W_DUP", 0.30)),
     "cog": float(os.environ.get("CODESEXTANT_W_COG", 0.30)),
     "bloat": float(os.environ.get("CODESEXTANT_W_BLOAT", 0.25))}

def _smoothstep(e0, e1, x):
    t = min(max((x - e0) / (e1 - e0), 0.0), 1.0)
    return t * t * (3 - 2 * t)

def _env_int(name: str, default: int) -> int:
    try:
        v = int(os.environ.get(name, ""))
        return v if v > 0 else default
    except ValueError:
        return default

def namegraph_enabled() -> bool:
    """名稱級邊是否啟用（預設啟用；CODESEXTANT_NAMEGRAPH_DISABLED 關閉）。"""
    return not _env_on("CODESEXTANT_NAMEGRAPH_DISABLED")

def _read_text(path: str) -> str | None:
    """讀檔成文字（errors=replace 不爆）；讀不到回 None。"""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            return f.read()
    except OSError:
        return None

def _normp(path: str) -> str:
    """路徑正規化 normcase(abspath) — 與 ranking._norm / storage.project_key 對齊。

    紅隊 L4-LOW 修正：原本只 abspath 不 normcase，Windows 上 'E:\\..\\M.py' vs 'e:\\..\\m.py'
    指同檔卻比不相等 → body 排除失效 → 定義行 self-token 漏排 → 真死碼漏報。全模組統一 normcase。
    """
    return os.path.normcase(os.path.abspath(path))

def _scan_cross_refs(symbols, indexed_files, read_text, max_fanout, max_files):
    """body-aware 掃全 repo 的核心（build_name_edges + compute_external_usage 共用，DRY）。

    回 (refs, defs, over_fanout, meta)：
      refs = [(src_norm, src_line, name, def_norm, def_line), ...]：每個「不落在自己定義 body 內」
             的已定義名 occurrence（一個 occurrence 一筆、不去重 → 保留引用次數）。src_line 記真
             occurrence 行號，給 compute_pagerank 把來源映射到真 caller 符號（非 collapse 到檔第一符號）。
      defs = _defs_by_name 結果。over_fanout = 同名定義超上限的名集合。meta = 掃描統計。

    body-aware：token 落在某定義自己的 [line,end_line] → 不算它的 ref（排定義行 self-token +
    遞迴）；同檔別符號 body 內 + 跨檔的 occurrence 都算（保留同檔真互呼叫）。over_fanout 名整個
    跳過。max_files 截斷防超大 repo（紅隊 L4-HIGH：compute_external_usage 原缺此保護 18k 檔卡死）。
    """
    defs = _defs_by_name(symbols)
    over_fanout = {n for n, lst in defs.items() if len(lst) > max_fanout}
    target_names = set(defs) - over_fanout
    meta = {"defined_names": len(defs), "scanned_files": 0, "total_files": 0,
            "truncated": False, "over_fanout_names": len(over_fanout),
            "skipped_fanout_names": len(over_fanout)}
    if not target_names:
        return [], defs, over_fanout, meta

    if indexed_files is None:
        indexed_files = sorted({_normp(s["path"]) for s in symbols if s.get("path")})
    else:
        indexed_files = [_normp(p) for p in indexed_files]
    meta["total_files"] = len(indexed_files)
    if len(indexed_files) > max_files:
        indexed_files = indexed_files[:max_files]
        meta["truncated"] = True

    refs: list[tuple[str, int, str, str, int]] = []
    for fp in indexed_files:
        text = read_text(fp)
        if not text:
            continue
        meta["scanned_files"] += 1
        for occ_line, line_text in enumerate(text.splitlines(), 1):
            for m in _IDENT_RE.finditer(line_text):
                name = m.group()
                if name not in target_names:
                    continue
                for (dp, dl, el) in defs[name]:
                    if fp == dp and dl <= occ_line <= el:
                        continue  # 落在自己 body → self-token，不算 ref
                    refs.append((fp, occ_line, name, dp, dl))
    return refs, defs, over_fanout, meta

