  .detail .row:last-child { border-bottom:none; }
  .detail .rk { color:var(--accent); }
  .muted { color:var(--faint); }
  .empty { color:var(--faint); text-align:center; padding:26px; font-size:13px; }
  .err-line { color:var(--err); font-size:12.5px; font-family:var(--mono); }
  .hint { color:var(--faint); font-size:11.5px; margin-top:8px; }
  a { color:var(--accent); text-decoration:none; }
  .spin { display:inline-block; width:11px; height:11px; border:2px solid var(--border);
    border-top-color:var(--accent); border-radius:50%; animation:s .7s linear infinite; vertical-align:-1px; }
  @keyframes s { to { transform:rotate(360deg); } }
</style>
</head>
<body>
<div class="wrap">
  <header>
    <div class="logo">碼</div>
    <h1>CodeSextant <small>CodeSextant · 代碼地圖總覽</small></h1>
    <span class="badge"><span id="hdot" class="dot"></span><span id="hstat">連線中…</span></span>
  </header>
  <div class="sub">常駐本機、零雲端零金鑰的代碼地圖服務——所有 AI 代理共用同一份「真 import 解析」全局關聯圖。</div>

  <div class="card">
    <h2>服務狀態</h2>
    <div id="health" class="grid"><div class="muted">載入中 <span class="spin"></span></div></div>
  </div>

  <div class="card">
    <h2>已索引專案 <span class="n" id="pcount">—</span></h2>
    <div class="toolbar">
      <span class="muted" id="dbdir"></span>
      <span class="spacer"></span>
      <button onclick="loadAll()">↻ 重新整理</button>
    </div>
    <div id="projects"><div class="empty">載入中 <span class="spin"></span></div></div>
    <div class="hint">「重建」＝重新索引（只重算改過的檔，增量很快）。「看地圖」＝列該專案 token 預算內最重要的符號。「查引用」＝某符號被誰呼叫。</div>
  </div>

  <div class="sub muted" style="text-align:center;margin-top:28px">
    CodeSextant daemon · <span id="footport"></span> · 此面板由 daemon <code>GET /</code> 提供，可嵌入 Tauri 殼或 AI King 擴充。
  </div>
</div>

<script>
const $ = (id) => document.getElementById(id);
const esc = (s) => String(s == null ? "" : s).replace(/[&<>"'`]/g, c =>
  ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;","`":"&#96;"}[c]));

function fmtTime(epoch) {
  if (!epoch) return "—";
  const d = new Date(epoch * 1000);
  const p = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}
function fmtUptime(sec) {
  if (sec == null) return "—";
  sec = Math.floor(sec);
  if (sec < 60) return sec + " 秒";
  if (sec < 3600) return Math.floor(sec/60) + " 分 " + (sec%60) + " 秒";
  return Math.floor(sec/3600) + " 小時 " + Math.floor((sec%3600)/60) + " 分";
}

async function api(path, opts) {
  const r = await fetch(path, opts);
  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(data.error || (r.status + " " + r.statusText));
  return data;
}

async function loadHealth() {
  try {
    const h = await api("/health");
    $("hdot").className = "dot ok";
    $("hstat").textContent = h["狀態"] || "就緒";
    $("footport").textContent = "127.0.0.1:" + h.port;
    const rows = [
      ["產品 / 服務", (h.product||"CodeSextant") + " / " + (h.service||"codesextant")],
      ["進程 PID", h.pid],
      ["連接埠 port", h.port],
      ["已運行", fmtUptime(h.uptime_sec)],
      ["引擎版本", h.engine_version || "—"],
      ["庫目錄", h["庫目錄"]],
      ["log 檔", h["log檔"]],
    ];
    $("health").innerHTML = rows.map(([k,v]) =>
      `<div class="kv"><span class="k">${esc(k)}</span><span class="v">${esc(v)}</span></div>`).join("");
  } catch (e) {
    $("hdot").className = "dot err";
    $("hstat").textContent = "離線";
    $("health").innerHTML = `<div class="err-line">無法連上 daemon：${esc(e.message)}</div>`;
  }
}

async function loadProjects() {
  try {
    const d = await api("/projects");
    $("pcount").textContent = d.count;
    $("dbdir").textContent = "庫目錄：" + d.db_dir;
    window.__projects = d.projects;
    if (!d.projects.length) {
      $("projects").innerHTML = `<div class="empty">尚無已索引專案。任一代理觸發 codesextant（或呼叫 /reindex）後會出現在這裡。</div>`;
      return;
    }
    const head = `<tr><th>專案路徑</th><th>檔</th><th>符號</th><th>引用邊</th><th>最後索引</th><th>操作</th></tr>`;
    // 用 project_key（sha1，全機唯一、與位置無關）當每列的 key——任何重排都不會錯位，
    // 與本專案「sha1 分庫不混線」紀律一致（位置下標在背景刷新後會對到錯的專案）。
    const body = d.projects.map((p) => {
      if (p.error) {
        return `<tr><td class="path">${esc(p.db_file)}</td><td colspan="5" class="err-line">${esc(p.error)}</td></tr>`;
      }
      const k = esc(p.project_key);
      const gone = p.path_exists === false;
      const pathCell = esc(p.repo_path || p.db_file) + (gone ? `<span class="tag gone">路徑已不存在</span>` : "");
      const acts = `<div class="actions">
        <button class="primary" data-act="reindex" data-key="${k}" ${gone?"disabled":""}>重建</button>
        <button data-act="map" data-key="${k}" ${gone?"disabled":""}>看地圖</button>
        <button data-act="refs" data-key="${k}" ${gone?"disabled":""}>查引用</button>
      </div>`;
      return `<tr class="${gone?"gone":""}">
        <td class="path">${pathCell}</td>
        <td class="num" id="files-${k}">${p.indexed_files}</td>
        <td class="num" id="syms-${k}">${p.symbols}</td>
        <td class="num" id="refs-${k}">${p.refs}</td>
        <td class="num muted" id="time-${k}">${fmtTime(p.last_indexed_at)}</td>
        <td>${acts}</td></tr>
        <tr id="detail-${k}" style="display:none"><td colspan="6"><div class="detail" id="detailbox-${k}"></div></td></tr>`;
    }).join("");
    $("projects").innerHTML = `<table>${head}${body}</table>`;
    $("projects").querySelectorAll("button[data-act]").forEach(b => {
      b.onclick = () => onAction(b.dataset.act, b.dataset.key, b);
    });
  } catch (e) {
    $("projects").innerHTML = `<div class="err-line">讀取專案列表失敗：${esc(e.message)}</div>`;
  }
}

function projByKey(key) { return (window.__projects || []).find(x => x.project_key === key); }

function showDetail(key, html) {
  const row = $("detail-" + key), box = $("detailbox-" + key);
  if (box) box.innerHTML = html;
  if (row) row.style.display = "";
}

async function refreshRowStats(key) {
  // reindex 後只更新該列數字（不整表重建）——保留其他已展開的 detail，
  // 也保留本列剛顯示的「重建完成」訊息（整表重建會把它清掉，M4）。
  try {
    const d = await api("/projects");
    window.__projects = d.projects;
    const p = d.projects.find(x => x.project_key === key);
    if (!p || p.error) return;
    const set = (id, v) => { const el = $(id + "-" + key); if (el) el.textContent = v; };
    set("files", p.indexed_files); set("syms", p.symbols);
    set("refs", p.refs); set("time", fmtTime(p.last_indexed_at));
  } catch (e) { /* 局部刷新失敗不影響已顯示的完成訊息 */ }
}

async function onAction(act, key, btn) {
  const p = projByKey(key);
  if (!p) return;
  if (act === "reindex") {
    const old = btn.textContent; btn.disabled = true; btn.innerHTML = '重建中 <span class="spin"></span>';
    try {
      const r = await api("/reindex", { method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ project: p.repo_path }) });
      showDetail(key, `<div class="row"><span class="rk">重建完成</span><span>新索引 ${r.indexed} 檔 · 略過 ${r.skipped} · 移除 ${r.removed} · 符號 ${r.symbols_total} · 耗時 ${r.elapsed_sec}s</span></div>`);
      await refreshRowStats(key);
    } catch (e) { showDetail(key, `<div class="err-line">重建失敗：${esc(e.message)}</div>`); }
    finally { btn.disabled = false; btn.textContent = old; }
  } else if (act === "map") {
    showDetail(key, `<span class="muted">載入地圖 <span class="spin"></span></span>`);
    try {
      const r = await api(`/get_map?project=${encodeURIComponent(p.repo_path)}&budget=1500`);
      const note = r.note ? `<div class="hint">${esc(r.note)}</div>` : "";
      const rows = (r.symbols||[]).map(s =>
        `<div class="row"><span class="rk">${esc(s.kind)} ${esc(s.name)}</span><span class="muted">${esc(shortPath(s.path, p.repo_path))}:${s.line}</span></div>`).join("");
      showDetail(key, `<div class="muted" style="margin-bottom:6px">最重要的 ${r.count} 個符號（約 ${r.approx_tokens} token）</div>${rows||'<div class="muted">無</div>'}${note}`);
    } catch (e) { showDetail(key, `<div class="err-line">看地圖失敗：${esc(e.message)}</div>`); }
  } else if (act === "refs") {
    showDetail(key, `<div style="display:flex;gap:8px;align-items:center">
      <input type="text" id="sym-${key}" placeholder="符號名（例：check）" style="flex:1">
      <button class="primary" id="symgo-${key}">查</button></div>
      <div id="symres-${key}" class="hint">輸入要查的函數 / 類別名稱，看它被哪些檔呼叫。</div>`);
    const go = async () => {
      const sym = $("sym-"+key).value.trim();
      if (!sym) return;
      const res = $("symres-"+key); res.innerHTML = `<span class="muted">jedi 解析中 <span class="spin"></span></span>`;
      try {
        const r = await api("/find_references", { method:"POST", headers:{"Content-Type":"application/json"},
          body: JSON.stringify({ project: p.repo_path, symbol: sym }) });
        const hi = r.high_confidence || [], lo = r.low_confidence || [];
        const cand = (r.candidate_definitions||[]).length;
        const hiRows = hi.slice(0,40).map(x =>
          `<div class="row"><span class="rk">${esc(shortPath(x.src_path, p.repo_path))}:${x.line}</span><span class="muted">高信心</span></div>`).join("");
        let warn = "";
        if (hi.length === 0 && lo.length > 0)
          warn = `<div class="hint">全部低信心——多半是 src-root 沒對（如 concinno 要指到 .../src），或此符號非定義在本專案。</div>`;
        res.innerHTML = `<div class="muted" style="margin-bottom:6px">候選定義 ${cand} 處 · 高信心引用 ${hi.length} · 低信心 ${lo.length}</div>${hiRows||'<div class="muted">無高信心引用</div>'}${warn}`;
      } catch (e) { res.innerHTML = `<div class="err-line">查引用失敗：${esc(e.message)}</div>`; }
    };
    $("symgo-"+key).onclick = go;
    $("sym-"+key).addEventListener("keydown", ev => { if (ev.key === "Enter") go(); });
    $("sym-"+key).focus();
  }
}

function shortPath(full, root) {
  if (full && root && full.startsWith(root)) return "." + full.slice(root.length);
  return full;
}

async function loadAll() { await Promise.all([loadHealth(), loadProjects()]); }
loadAll();
setInterval(loadHealth, 5000);  // 服務狀態每 5 秒自動刷新（uptime / 離線偵測）
</script>
</body>
</html>
"""

def render_panel() -> str:
    """回傳完整的中文面板 HTML（自包含、無外部依賴）。"""
    return _PANEL_HTML

def _env_float(name: str, default: float) -> float:
    try:
        return float(os.environ.get(name, ""))
    except ValueError:
        return default

def _env_int(name: str, default: int) -> int:
    try:
        return int(os.environ.get(name, ""))
    except ValueError:
        return default

def _well_named(name: str) -> bool:
    """命名規範的公開符號（含底線分隔或大小寫混合＝snake/camel/Pascal）。"""
    if name.startswith("_"):
        return False
    return ("_" in name) or (name != name.lower() and name != name.upper())

def _symbol_quality_mult(name: str, defines_count: int) -> float:
    """queue 5（邊權重符號品質係數，aider 啟發式）——凸顯架構性公開 API、壓低低訊號/氾濫符號。

    well-named 公開符號(len>=門檻) ×WELLNAMED；私有 _開頭 ×PRIVATE；在 >N 檔重複定義(過於常見、
    如 utils/handle/run 氾濫名) ×COMMON。全做 config（L0 鐵律 #6 可調）。
    """
    mult = 1.0
    if name.startswith("_"):
        mult *= _env_float("CODESEXTANT_RANK_PRIVATE_MULT", 0.1)
    elif len(name) >= _env_int("CODESEXTANT_RANK_WELLNAMED_MINLEN", 8) and _well_named(name):
        mult *= _env_float("CODESEXTANT_RANK_WELLNAMED_MULT", 10.0)
    if defines_count > _env_int("CODESEXTANT_RANK_COMMON_THRESHOLD", 5):
        mult *= _env_float("CODESEXTANT_RANK_COMMON_MULT", 0.1)
    return mult

def _build_personalization(symbols: list[dict], focus_symbols=None,
                           focus_files=None) -> dict | None:
    """queue 4（query-aware PageRank）——把呼叫端顯式傳入的 focus set 轉成 personalization 向量。

    ⛔ boost 來源是「呼叫端顯式說我在改 X」(focus_symbols/focus_files)，**非監聽對話/接 LLM**
    （守零雲端/不接 LLM 鐵則；aider 是聊天前端才監聽對話，CodeSextant 是被呼叫的導航工具）。
    focus 命中符號的 teleport 權重 +boost 倍。無 focus 回 None（退均勻 teleport＝原靜態行為）。
    """
    fs = set(focus_symbols or [])
    ff = {_norm(f) for f in (focus_files or [])}
    if not fs and not ff:
        return None
    boost = _env_float("CODESEXTANT_PAGERANK_FOCUS_BOOST", 10.0)
    p: dict[str, float] = {}
    for s in symbols:
        w = 1.0
        if s.get("name") in fs:
            w += boost
        if _norm(s.get("path")) in ff:
            w += boost
        p[_symbol_id(s)] = w
    return p

def compute_pagerank(symbols: list[dict], refs: list[dict],
                     *, damping: float = 0.85, max_iter: int = 100,
                     tol: float = 1.0e-6,
                     personalization: dict[str, float] | None = None) -> dict[str, float]:
    """對符號圖跑 PageRank，回傳 {symbol_id: score}。

    邊方向：src（引用端所在檔的代表符號）→ def（被引用的符號定義）。
    PageRank 讓分數從引用端流向被引用端，所以「被很多重要符號引用」的符號得高分。
    src 對應不到某個符號節點時（如模組頂層呼叫），當作「外部入流」均攤計入。

    queue 5：邊權重疊「被引用符號的品質係數」（well-named 公開 ×10 / 私有 ×0.1 / 過於常見 ×0.1）。
    queue 4：personalization（{symbol_id: 偏好權重}）灌進 teleport 向量＝query-aware 排序；
             None 退均勻 teleport（原靜態行為，向後相容）。

    symbols 為空回 {}。所有中間狀態皆為局部變數，呼叫間互不影響。
    """
    if not symbols:
        return {}

    node_ids: list[str] = [_symbol_id(s) for s in symbols]
    n = len(node_ids)
    idx = {sid: i for i, sid in enumerate(node_ids)}
    name_of: dict[str, str] = {sid: symbols[i]["name"] for i, sid in enumerate(node_ids)}
    # queue 5：name → 在幾個 distinct 檔定義（過於常見＝低訊號，邊權重打折）
    from collections import Counter
    _seen_np: set = set()
    defines: "Counter[str]" = Counter()
    for s in symbols:
        k = (s["name"], _norm(s.get("path")))
        if k not in _seen_np:
            _seen_np.add(k)
            defines[s["name"]] += 1

    # (檔絕對路徑, 定義行) → symbol_id，讓引用邊的 def_path/def_line 對上節點
    by_pos: dict[tuple, str] = {}
    # 檔絕對路徑 → 該檔第一個符號的 symbol_id（當引用端的代表節點）
    file_rep: dict[str, str] = {}
    for s in symbols:
        sid = _symbol_id(s)
        p = s.get("path")
        if p is None:
            continue
        np = _norm(p)
        by_pos[(np, s["line"])] = sid
        cur = file_rep.get(np)
        if cur is None or s["line"] < _line_of(cur):
            file_rep[np] = sid

    # path → sorted [(line, end_line, sid)]：給「src_line 映射到包含它的 caller 符號」用。
    # 紅隊 L1-HIGH 修正：同檔邊的來源用「真正包含 src_line 的 caller 符號」當節點，而非
    # collapse 到檔第一符號 file_rep——否則「被呼叫者剛好是檔第一符號」時邊成 i==j 被跳過，
    # 整個同檔/單模組引用結構對 PageRank 不可見（單檔專案原樣退回均分）。
    by_body: dict[str, list] = {}
    for s in symbols:
        p = s.get("path")
        if p is None:
            continue
        np = _norm(p)
        by_body.setdefault(np, []).append(
            (s["line"], int(s.get("end_line", s["line"]) or s["line"]), _symbol_id(s)))
    for lst in by_body.values():
        lst.sort()

    def _src_node(src_path, src_line):
        """src_line 映射到「包含它的最內層符號」當來源節點；無 src_line / 找不到 → fallback
        file_rep（向後相容：db 高信心邊有 src_line＝更精確的 caller；src_line=0 退 file_rep）。"""
        np = _norm(src_path) if src_path else ""
        if src_line and np in by_body:
            best = None
            for (ln, el, sid) in by_body[np]:
                if ln > src_line:
                    break
                if ln <= src_line <= el:
                    best = sid   # 持續更新→最內層（line 最大者）
            if best is not None:
                return best
        return file_rep.get(np)

    # 建鄰接 out_targets[i] = [(j, weight), ...]；以及外部入流 external_inflow[j]
    out_targets: list[list[tuple[int, float]]] = [[] for _ in range(n)]
    external_inflow: dict[int, float] = {}

    for e in refs:
        dp, dl = e.get("def_path"), e.get("def_line")
        if dp is None or dl is None:
            continue
        target = by_pos.get((_norm(dp), dl))
        if target is None:
            continue
        j = idx[target]
        w = _CONFIDENCE_WEIGHT.get(e.get("confidence", "low"), 0.25)
        # queue 5：疊被引用符號的品質係數（well-named 公開 ×10 / 私有 ×0.1 / 過於常見 ×0.1）
        tname = name_of.get(target, "")
        w *= _symbol_quality_mult(tname, defines.get(tname, 1))

        src_rep = _src_node(e.get("src_path"), e.get("src_line"))
        if src_rep is None:
            external_inflow[j] = external_inflow.get(j, 0.0) + w
            continue
        i = idx[src_rep]
        if i == j:
            continue
        out_targets[i].append((j, w))

    n_refs = max(1, len(refs))
    # queue 4：personalization teleport 向量 P（focus 偏好）；無則均勻 1/n（原靜態行為，向後相容）
    if personalization:
        tot_p = sum(personalization.get(sid, 1.0) for sid in node_ids) or 1.0
        P = [personalization.get(node_ids[j], 1.0) / tot_p for j in range(n)]
    else:
        P = [1.0 / n] * n
    score = list(P)

    for _ in range(max_iter):
        new_score = [(1.0 - damping) * P[j] for j in range(n)]
        dangling_sum = 0.0
        for i in range(n):
            edges = out_targets[i]
            if not edges:
                dangling_sum += score[i]
                continue
            total_w = sum(w for _, w in edges)
            if total_w <= 0:
                dangling_sum += score[i]
                continue
            for j, w in edges:
                new_score[j] += damping * score[i] * (w / total_w)
        if dangling_sum:
            # dangling 質量按 personalization 分布回流（aider dangling=P）
            for j in range(n):
                new_score[j] += damping * dangling_sum * P[j]
        for j, infl in external_inflow.items():
            new_score[j] += damping * infl / n_refs

        delta = sum(abs(new_score[i] - score[i]) for i in range(n))
        score = new_score
        if delta < tol:
            break

    return {node_ids[i]: score[i] for i in range(n)}

def _src_node(src_path, src_line):
    """src_line 映射到「包含它的最內層符號」當來源節點；無 src_line / 找不到 → fallback
    file_rep（向後相容：db 高信心邊有 src_line＝更精確的 caller；src_line=0 退 file_rep）。"""
    np = _norm(src_path) if src_path else ""
    if src_line and np in by_body:
        best = None
        for (ln, el, sid) in by_body[np]:
            if ln > src_line:
                break
            if ln <= src_line <= el:
                best = sid   # 持續更新→最內層（line 最大者）
        if best is not None:
            return best
    return file_rep.get(np)

def _line_of(sid: str) -> int:
    """從 symbol_id 取出 line（id 格式 path::scope::name::line）。"""
    try:
        return int(sid.rsplit("::", 1)[1])
    except (IndexError, ValueError):
        return 1 << 30

def _word_re(symbol: str) -> "re.Pattern":
    pat = _word_re_cache.get(symbol)
    if pat is None:
        pat = re.compile(r"\b" + re.escape(symbol) + r"\b")
        _word_re_cache[symbol] = pat
    return pat

def _iter_python_files(root: str):
    for dirpath, dirnames, filenames in os.walk(root):
        # 跳過常見的雜訊目錄（避免掃 .git / venv / __pycache__）
        dirnames[:] = [d for d in dirnames
                       if d not in (".git", "__pycache__", ".venv", "venv",
                                    "node_modules", ".mypy_cache", ".pytest_cache")]
        for fn in filenames:
            if fn.endswith(".py"):
                yield os.path.join(dirpath, fn)

def _prefilter_candidate_files(src_root: str, symbol: str) -> list[str]:
    """第一段（粗篩）：名稱出現在哪些檔。便宜、寬鬆，寧可多框幾個。

    回傳含該符號名（當作獨立 word）的所有 .py 檔。jedi 只精解這些。
    """
    pat = _word_re(symbol)
    candidates: list[str] = []
    for fp in _iter_python_files(src_root):
        try:
            with open(fp, "r", encoding="utf-8", errors="replace") as f:
                text = f.read()
        except OSError:
            continue
        if pat.search(text):
            candidates.append(fp)
    return candidates

def _make_project(src_root: str) -> "jedi.Project":
    """每專案一個 jedi.Project（天然按專案根隔離）。"""
    return jedi.Project(path=os.path.abspath(src_root))

def _locate_definition_position(src_root: str, def_name: str,
                                def_path: str | None) -> tuple[str, int, int] | None:
    """在定義檔裡定位 `def_name` 的 def/class 那一行（jedi get_references 要有起點）。

    若給了 def_path 就只找該檔；否則跨 src_root 找第一個命中。
    回傳 (path, line, column 1-based 指到名稱起點) 或 None。
    """
    pat = re.compile(r"^\s*(?:async\s+)?(?:def|class)\s+(" + re.escape(def_name) + r")\b")
    search_files = [def_path] if def_path else list(_iter_python_files(src_root))
    for fp in search_files:
        if not fp or not os.path.exists(fp):
            continue
        try:
            with open(fp, "r", encoding="utf-8", errors="replace") as f:
                for i, line_text in enumerate(f, 1):
                    m = pat.match(line_text)
                    if m:
                        return (fp, i, m.start(1) + 1)
        except OSError:
            continue
    return None

def _occurrences_in_file(file_path: str, symbol: str) -> list[tuple[int, int]]:
    """檔內 `symbol`（當獨立 word）每個出現位置，回 [(line 1-based, col 0-based), ...]。

    col 用 0-based（jedi goto/column 慣例）。供第二段對每個出現點做 goto 用。
    """
    pat = _word_re(symbol)
    out: list[tuple[int, int]] = []
    try:
        with open(file_path, "r", encoding="utf-8", errors="replace") as f:
            for li, line_text in enumerate(f, 1):
                for m in pat.finditer(line_text):
                    out.append((li, m.start()))
    except OSError:
        pass
    return out

def _iter_files_by_ext(root: str, exts):
    """掃 root 下指定副檔名的檔（跳過雜訊目錄）。給跨語言名稱比對用。"""
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in _SKIP_DIRS_MULTI]
        for fn in filenames:
            if os.path.splitext(fn)[1].lower() in exts:
                yield os.path.join(dirpath, fn)

def _ts_bridge_dir() -> str:
    """ts_bridge/ 在 CodeSextant 根（references.py 在 codesextant/ 內、上一層即根）。"""
    return os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "ts_bridge")

def ts_morph_available() -> bool:
    """node 在 PATH 且 ts_bridge 已備妥（find_refs.mjs + node_modules/ts-morph）。
    任一不滿足 → 回 False，呼叫端據此 fallback 回 C5a 名稱比對（不爆）。

    開關（L0 鐵律 #6）：env CODESEXTANT_TS_MORPH_DISABLED=1 → 強制停用 ts-morph、
    一律走 C5a 名稱比對（給「不想要 Node 子進程」或除錯時用）。"""
    if os.environ.get("CODESEXTANT_TS_MORPH_DISABLED", "").lower() in ("1", "true", "yes", "on"):
        return False
    if shutil.which("node") is None:
        return False
    bridge = _ts_bridge_dir()
    return (os.path.isfile(os.path.join(bridge, "find_refs.mjs"))
            and os.path.isdir(os.path.join(bridge, "node_modules", "ts-morph")))

def _run_ts_bridge(payload: dict, timeout: float) -> dict | None:
    """跑 ts_bridge/find_refs.mjs（stdin JSON → stdout JSON）。失敗/畸形/逾時 → None。永不拋。

    用 bytes stdin（UTF-8）——中文路徑經 stdin 不會像 PS Invoke-WebRequest 那樣編碼壞。
    CREATE_NO_WINDOW（Windows）：不彈 node 黑窗干擾 user（2026-06-19 user 反映補上、序4+5 沿用）。
    """
    bridge = _ts_bridge_dir()
    raw = json.dumps(payload).encode("utf-8")
    try:
        _kw = {"input": raw, "capture_output": True, "cwd": bridge, "timeout": timeout}
        if os.name == "nt":
            _kw["creationflags"] = 0x08000000  # CREATE_NO_WINDOW
        proc = subprocess.run(["node", os.path.join(bridge, "find_refs.mjs")], **_kw)
    except (subprocess.TimeoutExpired, OSError):
        return None
    if proc.returncode != 0:
        return None
    try:
        data = json.loads(proc.stdout.decode("utf-8", "replace"))
    except json.JSONDecodeError:
        return None
    return data if isinstance(data, dict) else None

def ts_morph_references(src_root: str, symbol: str, *, def_path: str | None,
                        timeout: float | None = None) -> dict | None:
    """單一符號 TS/JS 高信心 import 解析（findReferences 排除同名干擾）。

    不可用（無 node / 未 npm install / 子進程失敗 / 逾時 / 找不到定義 / 輸出畸形）→ 回 None，
    讓呼叫端 fallback 回 name_match_references（C5a 名稱比對）。**永不拋**。

    timeout：None 時取 env CODESEXTANT_TS_MORPH_TIMEOUT（預設 30 秒；L0 鐵律 #6 可調閾值
    ——超大 TS 專案 ts-morph 載入較久時可調高，逾時會靜默降級成名稱比對）。
    """
    if not def_path or not ts_morph_available():
        return None
    if timeout is None:
        try:
            timeout = float(os.environ.get("CODESEXTANT_TS_MORPH_TIMEOUT", "30"))
        except ValueError:
            timeout = 30.0
    data = _run_ts_bridge({
        "projectRoot": os.path.abspath(src_root),
        "defFile": os.path.abspath(def_path),
        "symbol": symbol,
    }, timeout)
    if data is None:
        return None
    # ts-morph 找不到定義（error 且無引用）→ 視為不可用，讓 fallback 名稱比對（一般查詢場景）
    if data.get("error") and not data.get("high_confidence"):
        return None
    try:
        return _shape_ts_one(symbol, data)
    except (KeyError, TypeError, AttributeError):
        return None

def ts_morph_references_batch(src_root: str, def_file: str, symbols,
                              *, timeout: float | None = None) -> dict | None:
    """序5：一次 spawn node 批查「同一檔多符號」（orphan 專用，避免逐符號各重載整個專案）。

    回 {symbol: result_dict|None}；ts-morph 不可用 / 子進程失敗 / 輸出畸形 → None
    （呼叫端據此逐符號 fallback 或整批標 UNKNOWN）。**永不拋**。

    與單一版的關鍵差異：error **不**回 None 而是帶 error 的 dict——orphan 場景要的是「ts-morph
    沒定位到 → UNKNOWN_UNRESOLVED」，⛔ 不該 fallback 名稱比對給低信心垃圾冒充。

    timeout：None 時取 env CODESEXTANT_TS_MORPH_BATCH_TIMEOUT（預設 90 秒；批量符號多、給更長）。
    """
    syms = [s for s in (symbols or []) if s]
    if not syms or not def_file or not ts_morph_available():
        return None
    if timeout is None:
        try:
            timeout = float(os.environ.get("CODESEXTANT_TS_MORPH_BATCH_TIMEOUT", "90"))
        except ValueError:
            timeout = 90.0
    data = _run_ts_bridge({
        "projectRoot": os.path.abspath(src_root),
        "defFile": os.path.abspath(def_file),
        "symbols": syms,
    }, timeout)
    if data is None:
        return None
    results = data.get("results")
    if not isinstance(results, dict):
        return None
    out: dict = {}
    for sym in syms:
        r = results.get(sym)
        try:
            out[sym] = _shape_ts_one(sym, r) if isinstance(r, dict) else None
        except (KeyError, TypeError, AttributeError):
            out[sym] = None
    return out

def db_path_for(repo_path: str) -> Path:
    """某專案對應的 SQLite 庫檔路徑。"""
    return default_db_dir() / f"{project_key(repo_path)}.db"

def file_content_hash(path: str) -> str:
    """檔案內容 sha256（增量的失效 key）。"""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()

